window.TXB=window.TXB||{};TXB["svd/Lev"]={"1:1":"ودعا الرب موسى وكلمه من خيمة الاجتماع قائلا:","1:2":"«كلم بني إسرائيل وقل لهم: إذا قرب إنسان منكم قربانا للرب من البهائم, فمن البقر والغنم تقربون قرابينكم.","1:3":"إن كان قربانه محرقة من البقر, فذكرا صحيحا يقربه. إلى باب خيمة الاجتماع يقدمه للرضا عنه أمام الرب.","1:4":"ويضع يده على رأس المحرقة, فيرضى عليه للتكفير عنه.","1:5":"ويذبح العجل أمام الرب, ويقرب بنو هارون الكهنة الدم, ويرشونه مستديرا على المذبح الذي لدى باب خيمة الاجتماع.","1:6":"ويسلخ المحرقة ويقطعها إلى قطعها.","1:7":"ويجعل بنو هارون الكاهن نارا على المذبح, ويرتبون حطبا على النار.","1:8":"ويرتب بنو هارون الكهنة القطع مع الرأس والشحم فوق الحطب الذي على النار التي على المذبح.","1:9":"وأما أحشاؤه وأكارعه فيغسلها بماء, ويوقد الكاهن الجميع على المذبح محرقة, وقود رائحة سرور للرب.","1:10":"«وإن كان قربانه من الغنم الضأن أو المعز محرقة, فذكرا صحيحا يقربه.","1:11":"ويذبحه على جانب المذبح إلى الشمال أمام الرب, ويرش بنو هارون الكهنة دمه على المذبح مستديرا.","1:12":"ويقطعه إلى قطعه, مع رأسه وشحمه. ويرتبهن الكاهن فوق الحطب الذي على النار التي على المذبح.","1:13":"وأما الأحشاء والأكارع فيغسلها بماء, ويقرب الكاهن الجميع, ويوقد على المذبح. إنه محرقة, وقود رائحة سرور للرب.","1:14":"«وإن كان قربانه للرب من الطير محرقة, يقرب قربانه من اليمام أو من أفراخ الحمام.","1:15":"يقدمه الكاهن إلى المذبح, ويحز رأسه, ويوقد على المذبح, ويعصر دمه على حائط المذبح.","1:16":"وينزع حوصلته بفرثها ويطرحها إلى جانب المذبح شرقا إلى مكان الرماد.","1:17":"ويشقه بين جناحيه. لا يفصله. ويوقده الكاهن على المذبح فوق الحطب الذي على النار. إنه محرقة, وقود رائحة سرور للرب.","2:1":"«وإذا قرب أحد قربان تقدمة للرب, يكون قربانه من دقيق. ويسكب عليها زيتا, ويجعل عليها لبانا.","2:2":"ويأتي بها إلى بني هارون الكهنة, ويقبض منها ملء قبضته من دقيقها وزيتها مع كل لبانها, ويوقد الكاهن تذكارها على المذبح, وقود رائحة سرور للرب.","2:3":"والباقي من التقدمة هو لهارون وبنيه, قدس أقداس من وقائد الرب.","2:4":"«وإذا قربت قربان تقدمة مخبوزة في تنور, تكون أقراصا من دقيق, فطيرا ملتوتة بزيت, ورقاقا فطيرا مدهونة بزيت.","2:5":"وإن كان قربانك تقدمة على الصاج, تكون من دقيق ملتوتة بزيت, فطيرا.","2:6":"تفتها فتاتا وتسكب عليها زيتا. إنها تقدمة.","2:7":"«وإن كان قربانك تقدمة من طاجن, فمن دقيق بزيت تعمله.","2:8":"فتأتي بالتقدمة التي تصطنع من هذه إلى الرب وتقدمها إلى الكاهن, فيدنو بها إلى المذبح.","2:9":"ويأخذ الكاهن من التقدمة تذكارها ويوقد على المذبح وقود رائحة سرور للرب.","2:10":"والباقي من التقدمة هو لهارون وبنيه, قدس أقداس من وقائد الرب.","2:11":"«كل التقدمات التي تقربونها للرب لا تصطنع خميرا, لأن كل خمير, وكل عسل لا توقدوا منهما وقودا للرب.","2:12":"قربان أوائل تقربونهما للرب. لكن على المذبح لا يصعدان لرائحة سرور.","2:13":"وكل قربان من تقادمك بالملح تملحه, ولا تخل تقدمتك من ملح عهد إلهك. على جميع قرابينك تقرب ملحا.","2:14":"«وإن قربت تقدمة باكورات للرب, ففريكا مشويا بالنار. جريشا سويقا تقرب تقدمة باكوراتك.","2:15":"وتجعل عليها زيتا وتضع عليها لبانا. إنها تقدمة.","2:16":"فيوقد الكاهن تذكارها من جريشها وزيتها مع جميع لبانها وقودا للرب.","3:1":"«وإن كان قربانه ذبيحة سلامة, فإن قرب من البقر ذكرا أو أنثى, فصحيحا يقربه أمام الرب.","3:2":"يضع يده على رأس قربانه ويذبحه لدى باب خيمة الاجتماع, ويرش بنو هارون الكهنة الدم على المذبح مستديرا.","3:3":"ويقرب من ذبيحة السلامة وقودا للرب: الشحم الذي يغشي الأحشاء, وسائر الشحم الذي على الأحشاء,","3:4":"والكليتين, والشحم الذي عليهما الذي على الخاصرتين, وزيادة الكبد مع الكليتين ينزعها.","3:5":"ويوقدها بنو هارون على المذبح على المحرقة التي فوق الحطب الذي على النار, وقود رائحة سرور للرب.","3:6":"«وإن كان قربانه من الغنم ذبيحة سلامة للرب ذكرا أو أنثى, فصحيحا يقربه.","3:7":"إن قرب قربانه من الضأن يقدمه أمام الرب.","3:8":"يضع يده على رأس قربانه ويذبحه قدام خيمة الاجتماع. ويرش بنو هارون دمه على المذبح مستديرا.","3:9":"ويقرب من ذبيحة السلامة شحمها وقودا للرب: الألية صحيحة من عند العصعص ينزعها, والشحم الذي يغشي الأحشاء, وسائر الشحم الذي على الأحشاء,","3:10":"والكليتين, والشحم الذي عليهما الذي على الخاصرتين, وزيادة الكبد مع الكليتين ينزعها.","3:11":"ويوقدها الكاهن على المذبح طعام وقود للرب.","3:12":"«وإن كان قربانه من المعز يقدمه أمام الرب.","3:13":"يضع يده على رأسه ويذبحه قدام خيمة الاجتماع, ويرش بنو هارون دمه على المذبح مستديرا.","3:14":"ويقرب منه قربانه وقودا للرب: الشحم الذي يغشي الأحشاء, وسائر الشحم الذي على الأحشاء,","3:15":"والكليتين والشحم الذي عليهما الذي على الخاصرتين, وزيادة الكبد مع الكليتين ينزعها.","3:16":"ويوقدهن الكاهن على المذبح طعام وقود لرائحة سرور. كل الشحم للرب.","3:17":"فريضة دهرية في أجيالكم في جميع مساكنكم: لا تأكلوا شيئا من الشحم ولا من الدم».","4:1":"وكلم الرب موسى قائلا:","4:2":"«كلم بني إسرائيل قائلا: إذا أخطأت نفس سهوا في شيء من جميع مناهي الرب التي لا ينبغي عملها, وعملت واحدة منها:","4:3":"إن كان الكاهن الممسوح يخطئ لإثم الشعب, يقرب عن خطيته التي أخطأ ثورا ابن بقر صحيحا للرب, ذبيحة خطية.","4:4":"يقدم الثور إلى باب خيمة الاجتماع أمام الرب, ويضع يده على رأس الثور, ويذبح الثور أمام الرب.","4:5":"ويأخذ الكاهن الممسوح من دم الثور ويدخل به إلى خيمة الاجتماع,","4:6":"ويغمس الكاهن إصبعه في الدم وينضح من الدم سبع مرات أمام الرب لدى حجاب القدس.","4:7":"ويجعل الكاهن من الدم على قرون مذبح البخور العطر الذي في خيمة الاجتماع أمام الرب, وسائر دم الثور يصبه إلى أسفل مذبح المحرقة الذي لدى باب خيمة الاجتماع.","4:8":"وجميع شحم ثور الخطية ينزعه عنه. الشحم الذي يغشي الأحشاء, وسائر الشحم الذي على الأحشاء,","4:9":"والكليتين والشحم الذي عليهما الذي على الخاصرتين, وزيادة الكبد مع الكليتين ينزعها,","4:10":"كما تنزع من ثور ذبيحة السلامة. ويوقدهن الكاهن على مذبح المحرقة.","4:11":"وأما جلد الثور وكل لحمه مع رأسه وأكارعه وأحشائه وفرثه","4:12":"فيخرج سائر الثور إلى خارج المحلة إلى مكان طاهر, إلى مرمى الرماد, ويحرقها على حطب بالنار. على مرمى الرماد تحرق.","4:13":"«وإن سها كل جماعة إسرائيل, وأخفي أمر عن أعين المجمع, وعملوا واحدة من جميع مناهي الرب التي لا ينبغي عملها, وأثموا,","4:14":"ثم عرفت الخطية التي أخطأوا بها, يقرب المجمع ثورا ابن بقر ذبيحة خطية. يأتون به إلى قدام خيمة الاجتماع,","4:15":"ويضع شيوخ الجماعة أيديهم على رأس الثور أمام الرب, ويذبح الثور أمام الرب.","4:16":"ويدخل الكاهن الممسوح من دم الثور إلى خيمة الاجتماع,","4:17":"ويغمس الكاهن إصبعه في الدم, وينضح سبع مرات أمام الرب لدى الحجاب.","4:18":"ويجعل من الدم على قرون المذبح الذي أمام الرب في خيمة الاجتماع, وسائر الدم يصبه إلى أسفل مذبح المحرقة الذي لدى باب خيمة الاجتماع.","4:19":"وجميع شحمه ينزعه عنه ويوقده على المذبح.","4:20":"ويفعل بالثور كما فعل بثور الخطية. كذلك يفعل به. ويكفر عنهم الكاهن, فيصفح عنهم.","4:21":"ثم يخرج الثور إلى خارج المحلة ويحرقه كما أحرق الثور الأول. إنه ذبيحة خطية المجمع.","4:22":"«إذا أخطأ رئيس وعمل بسهو واحدة من جميع مناهي الرب إلهه التي لا ينبغي عملها, وأثم,","4:23":"ثم أعلم بخطيته التي أخطأ بها, يأتي بقربانه تيسا من المعز ذكرا صحيحا.","4:24":"ويضع يده على رأس التيس ويذبحه في الموضع الذي يذبح فيه المحرقة أمام الرب. إنه ذبيحة خطية.","4:25":"ويأخذ الكاهن من دم ذبيحة الخطية بإصبعه ويجعل على قرون مذبح المحرقة, ثم يصب دمه إلى أسفل مذبح المحرقة.","4:26":"وجميع شحمه يوقده على المذبح كشحم ذبيحة السلامة, ويكفر الكاهن عنه من خطيته فيصفح عنه.","4:27":"«وإن أخطأ أحد من عامة الأرض سهوا, بعمله واحدة من مناهي الرب التي لا ينبغي عملها, وأثم,","4:28":"ثم أعلم بخطيته التي أخطأ بها, يأتي بقربانه عنزا من المعز أنثى صحيحة عن خطيته التي أخطأ.","4:29":"ويضع يده على رأس ذبيحة الخطية, ويذبح ذبيحة الخطية في موضع المحرقة.","4:30":"ويأخذ الكاهن من دمها بإصبعه ويجعل على قرون مذبح المحرقة, ويصب سائر دمها إلى أسفل المذبح.","4:31":"وجميع شحمها ينزعه كما نزع الشحم عن ذبيحة السلامة, ويوقد الكاهن على المذبح رائحة سرور للرب ويكفر عنه الكاهن فيصفح عنه.","4:32":"«وإن أتى بقربانه من الضأن ذبيحة خطية, يأتي بها أنثى صحيحة.","4:33":"ويضع يده على رأس ذبيحة الخطية, ويذبحها ذبيحة خطية في الموضع الذي يذبح فيه المحرقة.","4:34":"ويأخذ الكاهن من دم ذبيحة الخطية بإصبعه ويجعل على قرون مذبح المحرقة, ويصب سائر الدم إلى أسفل المذبح.","4:35":"وجميع شحمه ينزعه كما ينزع شحم الضأن عن ذبيحة السلامة, ويوقده الكاهن على المذبح على وقائد الرب. ويكفر عنه الكاهن من خطيته التي أخطأ فيصفح عنه.","5:1":"«وإذا أخطأ أحد وسمع صوت حلف وهو شاهد يبصر أو يعرف, فإن لم يخبر به حمل ذنبه.","5:2":"أو إذا مس أحد شيئا نجسا: جثة وحش نجس, أو جثة بهيمة نجسة, أو جثة دبيب نجس, وأخفي عنه, فهو نجس ومذنب.","5:3":"أو إذا مس نجاسة إنسان من جميع نجاساته التي يتنجس بها, وأخفي عنه ثم علم, فهو مذنب.","5:4":"أو إذا حلف أحد مفترطا بشفتيه للإساءة أو للإحسان من جميع ما يفترط به الإنسان في اليمين, وأخفي عنه, ثم علم, فهو مذنب في شيء من ذلك.","5:5":"فإن كان يذنب في شيء من هذه, يقر بما قد أخطأ به.","5:6":"ويأتي إلى الرب بذبيحة لإثمه عن خطيته التي أخطأ بها: أنثى من الأغنام نعجة أو عنزا من المعز, ذبيحة خطية, فيكفر عنه الكاهن من خطيته.","5:7":"وإن لم تنل يده كفاية لشاة, فيأتي بذبيحة لإثمه الذي أخطأ به: يمامتين أو فرخي حمام إلى الرب, أحدهما ذبيحة خطية والآخر محرقة.","5:8":"يأتي بهما إلى الكاهن, فيقرب الذي للخطية أولا. يحز رأسه من قفاه ولا يفصله.","5:9":"وينضح من دم ذبيحة الخطية على حائط المذبح, والباقي من الدم يعصر إلى أسفل المذبح. إنه ذبيحة خطية.","5:10":"وأما الثاني فيعمله محرقة كالعادة, فيكفر عنه الكاهن من خطيته التي أخطأ, فيصفح عنه.","5:11":"وإن لم تنل يده يمامتين أو فرخي حمام فيأتي بقربانه عما أخطأ به عشر الإيفة من دقيق, قربان خطية. لا يضع عليه زيتا, ولا يجعل عليه لبانا لأنه قربان خطية.","5:12":"يأتي به إلى الكاهن فيقبض الكاهن منه ملء قبضته تذكاره, ويوقده على المذبح على وقائد الرب. إنه قربان خطية.","5:13":"فيكفر عنه الكاهن من خطيته التي أخطأ بها في واحدة من ذلك, فيصفح عنه. ويكون للكاهن كالتقدمة».","5:14":"وكلم الرب موسى قائلا:","5:15":"«إذا خان أحد خيانة وأخطأ سهوا في أقداس الرب, يأتي إلى الرب بذبيحة لإثمه: كبشا صحيحا من الغنم بتقويمك من شواقل فضة على شاقل القدس, ذبيحة إثم.","5:16":"ويعوض عما أخطأ به من القدس, ويزيد عليه خمسه, ويدفعه إلى الكاهن, فيكفر الكاهن عنه بكبش الإثم, فيصفح عنه.","5:17":"«وإذا أخطأ أحد وعمل واحدة من جميع مناهي الرب التي لا ينبغي عملها, ولم يعلم, كان مذنبا وحمل ذنبه.","5:18":"فيأتي بكبش صحيح من الغنم بتقويمك, ذبيحة إثم, إلى الكاهن, فيكفر عنه الكاهن من سهوه الذي سها وهو لا يعلم, فيصفح عنه.","5:19":"إنه ذبيحة إثم. قد أثم إثما إلى الرب».","6:1":"وكلم الرب موسى قائلا:","6:2":"«إذا أخطأ أحد وخان خيانة بالرب, وجحد صاحبه وديعة أو أمانة أو مسلوبا, أو اغتصب من صاحبه,","6:3":"أو وجد لقطة وجحدها, وحلف كاذبا على شيء من كل ما يفعله الإنسان مخطئا به,","6:4":"فإذا أخطأ وأذنب, يرد المسلوب الذي سلبه, أو المغتصب الذي اغتصبه, أو الوديعة التي أودعت عنده, أو اللقطة التي وجدها,","6:5":"أو كل ما حلف عليه كاذبا. يعوضه برأسه, ويزيد عليه خمسه. إلى الذي هو له يدفعه يوم ذبيحة إثمه.","6:6":"ويأتي إلى الرب بذبيحة لإثمه: كبشا صحيحا من الغنم بتقويمك, ذبيحة إثم إلى الكاهن.","6:7":"فيكفر عنه الكاهن أمام الرب, فيصفح عنه في الشيء من كل ما فعله مذنبا به».","6:8":"وكلم الرب موسى قائلا:","6:9":"«أوص هارون وبنيه قائلا: هذه شريعة المحرقة: هي المحرقة تكون على الموقدة فوق المذبح كل الليل حتى الصباح, ونار المذبح تتقد عليه.","6:10":"ثم يلبس الكاهن ثوبه من كتان, ويلبس سراويل من كتان على جسده, ويرفع الرماد الذي صيرت النار المحرقة إياه على المذبح, ويضعه بجانب المذبح.","6:11":"ثم يخلع ثيابه ويلبس ثيابا أخرى, ويخرج الرماد إلى خارج المحلة, إلى مكان طاهر.","6:12":"والنار على المذبح تتقد عليه. لا تطفأ. ويشعل عليها الكاهن حطبا كل صباح, ويرتب عليها المحرقة, ويوقد عليها شحم ذبائح السلامة.","6:13":"نار دائمة تتقد على المذبح. لا تطفأ.","6:14":"«وهذه شريعة التقدمة: يقدمها بنو هارون أمام الرب إلى قدام المذبح,","6:15":"ويأخذ منها بقبضته بعض دقيق التقدمة وزيتها وكل اللبان الذي على التقدمة, ويوقد على المذبح رائحة سرور تذكارها للرب.","6:16":"والباقي منها يأكله هارون وبنوه. فطيرا يؤكل في مكان مقدس. في دار خيمة الاجتماع يأكلونه.","6:17":"لا يخبز خميرا. قد جعلته نصيبهم من وقائدي. إنها قدس أقداس كذبيحة الخطية وذبيحة الإثم.","6:18":"كل ذكر من بني هارون يأكل منها. فريضة دهرية في أجيالكم من وقائد الرب. كل من مسها يتقدس».","6:19":"وكلم الرب موسى قائلا:","6:20":"«هذا قربان هارون وبنيه الذي يقربونه للرب يوم مسحته: عشر الإيفة من دقيق تقدمة دائمة, نصفها صباحا, ونصفها مساء.","6:21":"على صاج تعمل بزيت, مربوكة تأتي بها. ثرائد تقدمة, فتاتا تقربها رائحة سرور للرب.","6:22":"والكاهن الممسوح عوضا عنه من بنيه يعملها فريضة دهرية للرب. توقد بكمالها.","6:23":"وكل تقدمة كاهن تحرق بكمالها. لا تؤكل».","6:24":"وكلم الرب موسى قائلا:","6:25":"«كلم هارون وبنيه قائلا: هذه شريعة ذبيحة الخطية: في المكان الذي تذبح فيه المحرقة, تذبح ذبيحة الخطية أمام الرب. إنها قدس أقداس.","6:26":"الكاهن الذي يعملها للخطية يأكلها. في مكان مقدس تؤكل في دار خيمة الاجتماع.","6:27":"كل من مس لحمها يتقدس. وإذا انتثر من دمها على ثوب تغسل ما انتثر عليه في مكان مقدس.","6:28":"وأما إناء الخزف الذي تطبخ فيه فيكسر. وإن طبخت في إناء نحاس, يجلى ويشطف بماء.","6:29":"كل ذكر من الكهنة يأكل منها. إنها قدس أقداس.","6:30":"وكل ذبيحة خطية يدخل من دمها إلى خيمة الاجتماع للتكفير في القدس, لا تؤكل. تحرق بنار.","7:1":"«وهذه شريعة ذبيحة الإثم: إنها قدس أقداس.","7:2":"في المكان الذي يذبحون فيه المحرقة, يذبحون ذبيحة الإثم, ويرش دمها على المذبح مستديرا,","7:3":"ويقرب منها كل شحمها: الألية, والشحم الذي يغشي الأحشاء,","7:4":"والكليتين والشحم الذي عليهما, الذي على الخاصرتين, وزيادة الكبد مع الكليتين ينزعها.","7:5":"ويوقدهن الكاهن على المذبح وقودا للرب. إنها ذبيحة إثم.","7:6":"كل ذكر من الكهنة يأكل منها. في مكان مقدس تؤكل. إنها قدس أقداس.","7:7":"ذبيحة الإثم كذبيحة الخطية, لهما شريعة واحدة. الكاهن الذي يكفر بها تكون له.","7:8":"والكاهن الذي يقرب محرقة إنسان فجلد المحرقة التي يقربها يكون له.","7:9":"وكل تقدمة خبزت في التنور, وكل ما عمل في طاجن أو على صاج يكون للكاهن الذي يقربه.","7:10":"وكل تقدمة ملتوتة بزيت أو ناشفة تكون لجميع بني هارون, كل إنسان كأخيه.","7:11":"«وهذه شريعة ذبيحة السلامة. الذي يقربها للرب:","7:12":"إن قربها لأجل الشكر, يقرب على ذبيحة الشكر أقراص فطير ملتوتة بزيت, ورقاق فطير مدهونة بزيت, ودقيقا مربوكا أقراصا ملتوتة بزيت,","7:13":"مع أقراص خبز خمير يقرب قربانه على ذبيحة شكر سلامته.","7:14":"ويقرب منه واحدا من كل قربان رفيعة للرب, يكون للكاهن الذي يرش دم ذبيحة السلامة.","7:15":"ولحم ذبيحة شكر سلامته يؤكل يوم قربانه. لا يبقي منه شيئا إلى الصباح.","7:16":"وإن كانت ذبيحة قربانه نذرا أو نافلة, ففي يوم تقريبه ذبيحته تؤكل. وفي الغد يؤكل ما فضل منها.","7:17":"وأما الفاضل من لحم الذبيحة في اليوم الثالث فيحرق بالنار.","7:18":"وإن أكل من لحم ذبيحة سلامته في اليوم الثالث لا تقبل. الذي يقربها لا تحسب له, تكون نجاسة, والنفس التي تأكل منها تحمل ذنبها.","7:19":"واللحم الذي مس شيئا ما نجسا لا يؤكل. يحرق بالنار. واللحم يأكل كل طاهر منه.","7:20":"وأما النفس التي تأكل لحما من ذبيحة السلامة التي للرب ونجاستها عليها فتقطع تلك النفس من شعبها.","7:21":"والنفس التي تمس شيئا ما نجسا نجاسة إنسان أو بهيمة نجسة أو مكروها ما نجسا, ثم تأكل من لحم ذبيحة السلامة التي للرب, تقطع تلك النفس من شعبها».","7:22":"وكلم الرب موسى قائلا:","7:23":"«كلم بني إسرائيل قائلا: كل شحم ثور أو كبش أو ماعز لا تأكلوا.","7:24":"وأما شحم الميتة وشحم المفترسة فيستعمل لكل عمل, لكن أكلا لا تأكلوه.","7:25":"إن كل من أكل شحما من البهائم التي يقرب منها وقودا للرب تقطع من شعبها, النفس التي تأكل.","7:26":"وكل دم لا تأكلوا في جميع مساكنكم من الطير ومن البهائم.","7:27":"كل نفس تأكل شيئا من الدم تقطع تلك النفس من شعبها».","7:28":"وكلم الرب موسى قائلا:","7:29":"«كلم بني إسرائيل قائلا: الذي يقرب ذبيحة سلامته للرب, يأتي بقربانه إلى الرب من ذبيحة سلامته.","7:30":"يداه تأتيان بوقائد الرب. الشحم يأتي به مع الصدر. أما الصدر فلكي يردده ترديدا أمام الرب.","7:31":"فيوقد الكاهن الشحم على المذبح, ويكون الصدر لهارون وبنيه.","7:32":"والساق اليمنى تعطونها رفيعة للكاهن من ذبائح سلامتكم.","7:33":"الذي يقرب دم ذبيحة السلامة والشحم من بني هارون, تكون له الساق اليمنى نصيبا,","7:34":"لأن صدر الترديد وساق الرفيعة قد أخذتهما من بني إسرائيل من ذبائح سلامتهم وأعطيتهما لهارون الكاهن ولبنيه فريضة دهرية من بني إسرائيل».","7:35":"تلك مسحة هارون ومسحة بنيه من وقائد الرب يوم تقديمهم ليكهنوا للرب,","7:36":"التي أمر الرب أن تعطى لهم يوم مسحه إياهم من بني إسرائيل, فريضة دهرية في أجيالهم.","7:37":"تلك شريعة المحرقة, والتقدمة, وذبيحة الخطية, وذبيحة الإثم, وذبيحة الملء, وذبيحة السلامة,","7:38":"التي أمر الرب بها موسى في جبل سيناء, يوم أمره بني إسرائيل بتقريب قرابينهم للرب في برية سيناء.","8:1":"وكلم الرب موسى قائلا:","8:2":"«خذ هارون وبنيه معه, والثياب ودهن المسحة وثور الخطية والكبشين وسل الفطير,","8:3":"واجمع كل الجماعة إلى باب خيمة الاجتماع».","8:4":"ففعل موسى كما أمره الرب. فاجتمعت الجماعة إلى باب خيمة الاجتماع.","8:5":"ثم قال موسى للجماعة: «هذا ما أمر الرب أن يفعل».","8:6":"فقدم موسى هارون وبنيه وغسلهم بماء.","8:7":"وجعل عليه القميص ونطقه بالمنطقة وألبسه الجبة وجعل عليه الرداء, ونطقه بزنار الرداء وشده به.","8:8":"ووضع عليه الصدرة وجعل في الصدرة الأوريم والتميم.","8:9":"ووضع العمامة على رأسه, ووضع على العمامة إلى جهة وجهه صفيحة الذهب, الإكليل المقدس, كما أمر الرب موسى.","8:10":"ثم أخذ موسى دهن المسحة ومسح المسكن وكل ما فيه وقدسه,","8:11":"ونضح منه على المذبح سبع مرات, ومسح المذبح وجميع آنيته, والمرحضة وقاعدتها لتقديسها.","8:12":"وصب من دهن المسحة على رأس هارون ومسحه لتقديسه.","8:13":"ثم قدم موسى بني هارون وألبسهم أقمصة ونطقهم بمناطق وشد لهم قلانس, كما أمر الرب موسى.","8:14":"ثم قدم ثور الخطية, ووضع هارون وبنوه أيديهم على رأس ثور الخطية.","8:15":"فذبحه, وأخذ موسى الدم وجعله على قرون المذبح مستديرا بإصبعه, وطهر المذبح. ثم صب الدم إلى أسفل المذبح وقدسه تكفيرا عنه.","8:16":"وأخذ كل الشحم الذي على الأحشاء وزيادة الكبد والكليتين وشحمهما, وأوقده موسى على المذبح.","8:17":"وأما الثور: جلده ولحمه وفرثه, فأحرقه بنار خارج المحلة, كما أمر الرب موسى.","8:18":"ثم قدم كبش المحرقة, فوضع هارون وبنوه أيديهم على رأس الكبش.","8:19":"فذبحه, ورش موسى الدم على المذبح مستديرا.","8:20":"وقطع الكبش إلى قطعه. وأوقد موسى الرأس والقطع والشحم.","8:21":"وأما الأحشاء والأكارع فغسلها بماء, وأوقد موسى كل الكبش على المذبح. إنه محرقة لرائحة سرور. وقود هو للرب, كما أمر الرب موسى.","8:22":"ثم قدم الكبش الثاني, كبش الملء, فوضع هارون وبنوه أيديهم على رأس الكبش.","8:23":"فذبحه, وأخذ موسى من دمه وجعل على شحمة أذن هارون اليمنى, وعلى إبهام يده اليمنى, وعلى إبهام رجله اليمنى.","8:24":"ثم قدم موسى بني هارون وجعل من الدم على شحم آذانهم اليمنى, وعلى أباهم أيديهم اليمنى, وعلى أباهم أرجلهم اليمنى, ثم رش موسى الدم على المذبح مستديرا.","8:25":"ثم أخذ الشحم: الألية وكل الشحم الذي على الأحشاء, وزيادة الكبد والكليتين وشحمهما, والساق اليمنى,","8:26":"ومن سل الفطير الذي أمام الرب, أخذ قرصا واحدا فطيرا, وقرصا واحدا من الخبز بزيت, ورقاقة واحدة, ووضعها على الشحم وعلى الساق اليمنى,","8:27":"وجعل الجميع على كفي هارون وكفوف بنيه, ورددها ترديدا أمام الرب.","8:28":"ثم أخذها موسى عن كفوفهم, وأوقدها على المذبح فوق المحرقة. إنها قربان ملء لرائحة سرور. وقود هي للرب.","8:29":"ثم أخذ موسى الصدر وردده ترديدا أمام الرب من كبش الملء. لموسى كان نصيبا, كما أمر الرب موسى.","8:30":"ثم أخذ موسى من دهن المسحة ومن الدم الذي على المذبح, ونضح على هارون وعلى ثيابه, وعلى بنيه وعلى ثياب بنيه معه. وقدس هارون وثيابه وبنيه وثياب بنيه معه.","8:31":"ثم قال موسى لهارون وبنيه: «اطبخوا اللحم لدى باب خيمة الاجتماع, وهناك تأكلونه والخبز الذي في سل قربان الملء, كما أمرت قائلا: هارون وبنوه يأكلونه.","8:32":"والباقي من اللحم والخبز تحرقونه بالنار.","8:33":"ومن لدن باب خيمة الاجتماع, لا تخرجون سبعة أيام إلى يوم كمال أيام ملئكم, لأنه سبعة أيام يملأ أيديكم.","8:34":"كما فعل في هذا اليوم, قد أمر الرب أن يفعل للتكفير عنكم.","8:35":"ولدى باب خيمة الاجتماع تقيمون نهارا وليلا سبعة أيام, وتحفظون شعائر الرب فلا تموتون, لأني هكذا أمرت».","8:36":"فعمل هارون وبنوه كل ما أمر به الرب على يد موسى.","9:1":"وفي اليوم الثامن دعا موسى هارون وبنيه وشيوخ إسرائيل.","9:2":"وقال لهارون: «خذ لك عجلا ابن بقر لذبيحة خطية, وكبشا لمحرقة صحيحين, وقدمهما أمام الرب.","9:3":"وكلم بني إسرائيل قائلا: خذوا تيسا من المعز لذبيحة خطية, وعجلا وخروفا حوليين صحيحين لمحرقة,","9:4":"وثورا وكبشا لذبيحة سلامة للذبح أمام الرب, وتقدمة ملتوتة بزيت. لأن الرب اليوم يتراءى لكم».","9:5":"فأخذوا ما أمر به موسى إلى قدام خيمة الاجتماع. وتقدم كل الجماعة ووقفوا أمام الرب.","9:6":"فقال موسى: «هذا ما أمر به الرب. تعملونه فيتراءى لكم مجد الرب».","9:7":"ثم قال موسى لهارون: «تقدم إلى المذبح واعمل ذبيحة خطيتك ومحرقتك, وكفر عن نفسك وعن الشعب. واعمل قربان الشعب وكفر عنهم كما أمر الرب».","9:8":"فتقدم هارون إلى المذبح وذبح عجل الخطية الذي له.","9:9":"وقدم بنو هارون إليه الدم, فغمس إصبعه في الدم وجعل على قرون المذبح, ثم صب الدم إلى أسفل المذبح.","9:10":"والشحم والكليتين وزيادة الكبد من ذبيحة الخطية أوقدها على المذبح, كما أمر الرب موسى.","9:11":"وأما اللحم والجلد فأحرقهما بنار خارج المحلة.","9:12":"ثم ذبح المحرقة, فناوله بنو هارون الدم, فرشه على المذبح مستديرا.","9:13":"ثم ناولوه المحرقة بقطعها والرأس, فأوقدها على المذبح.","9:14":"وغسل الأحشاء والأكارع وأوقدها فوق المحرقة على المذبح.","9:15":"ثم قدم قربان الشعب, وأخذ تيس الخطية الذي للشعب وذبحه وعمله للخطية كالأول.","9:16":"ثم قدم المحرقة وعملها كالعادة.","9:17":"ثم قدم التقدمة وملأ كفه منها, وأوقدها على المذبح, عدا محرقة الصباح.","9:18":"ثم ذبح الثور والكبش ذبيحة السلامة التي للشعب. وناوله بنو هارون الدم فرشه على المذبح مستديرا.","9:19":"والشحم من الثور ومن الكبش: الألية وما يغشي, والكليتين وزيادة الكبد.","9:20":"ووضعوا الشحم على الصدرين, فأوقد الشحم على المذبح.","9:21":"وأما الصدران والساق اليمنى فرددها هارون ترديدا أمام الرب, كما أمر موسى.","9:22":"ثم رفع هارون يده نحو الشعب وباركهم, وانحدر من عمل ذبيحة الخطية والمحرقة وذبيحة السلامة.","9:23":"ودخل موسى وهارون إلى خيمة الاجتماع, ثم خرجا وباركا الشعب, فتراءى مجد الرب لكل الشعب","9:24":"وخرجت نار من عند الرب وأحرقت على المذبح المحرقة والشحم. فرأى جميع الشعب وهتفوا وسقطوا على وجوههم.","10:1":"وأخذ ابنا هارون: ناداب وأبيهو, كل منهما مجمرته وجعلا فيهما نارا ووضعا عليها بخورا, وقربا أمام الرب نارا غريبة لم يأمرهما بها.","10:2":"فخرجت نار من عند الرب وأكلتهما, فماتا أمام الرب.","10:3":"فقال موسى لهارون: «هذا ما تكلم به الرب قائلا: في القريبين مني أتقدس, وأمام جميع الشعب أتمجد». فصمت هارون.","10:4":"فدعا موسى ميشائيل وألصافان ابني عزيئيل عم هارون, وقال لهما: «تقدما ارفعا أخويكما من قدام القدس إلى خارج المحلة».","10:5":"فتقدما ورفعاهما في قميصيهما إلى خارج المحلة, كما قال موسى.","10:6":"وقال موسى لهارون وألعازار وإيثامار ابنيه: «لا تكشفوا رؤوسكم ولا تشقوا ثيابكم لئلا تموتوا, ويسخط على كل الجماعة. وأما إخوتكم كل بيت إسرائيل فيبكون على الحريق الذي أحرقه الرب.","10:7":"ومن باب خيمة الاجتماع لا تخرجوا لئلا تموتوا, لأن دهن مسحة الرب عليكم». ففعلوا حسب كلام موسى.","10:8":"وكلم الرب هارون قائلا:","10:9":"«خمرا ومسكرا لا تشرب أنت وبنوك معك عند دخولكم إلى خيمة الاجتماع لكي لا تموتوا. فرضا دهريا في أجيالكم","10:10":"وللتمييز بين المقدس والمحلل وبين النجس والطاهر,","10:11":"ولتعليم بني إسرائيل جميع الفرائض التي كلمهم الرب بها بيد موسى».","10:12":"وقال موسى لهارون وألعازار وإيثامار ابنيه الباقيين: «خذوا التقدمة الباقية من وقائد الرب وكلوها فطيرا بجانب المذبح لأنها قدس أقداس.","10:13":"كلوها في مكان مقدس لأنها فريضتك وفريضة بنيك من وقائد الرب, فإنني هكذا أمرت.","10:14":"وأما صدر الترديد وساق الرفيعة فتأكلونهما في مكان طاهر أنت وبنوك وبناتك معك, لأنهما جعلا فريضتك وفريضة بنيك من ذبائح سلامة بني إسرائيل.","10:15":"ساق الرفيعة وصدر الترديد يأتون بهما مع وقائد الشحم ليرددا ترديدا أمام الرب, فيكونان لك ولبنيك معك فريضة دهرية, كما أمر الرب».","10:16":"وأما تيس الخطية فإن موسى طلبه فإذا هو قد احترق. فسخط على ألعازار وإيثامار, ابني هارون الباقيين, وقال:","10:17":"«ما لكما لم تأكلا ذبيحة الخطية في المكان المقدس؟ لأنها قدس أقداس, وقد أعطاكما إياها لتحملا إثم الجماعة تكفيرا عنهم أمام الرب.","10:18":"إنه لم يؤت بدمها إلى القدس داخلا. أكلا تأكلانها في القدس كما أمرت».","10:19":"فقال هارون لموسى: «إنهما اليوم قد قربا ذبيحة خطيتهما ومحرقتهما أمام الرب, وقد أصابني مثل هذه. فلو أكلت ذبيحة الخطية اليوم, هل كان يحسن في عيني الرب؟».","10:20":"فلما سمع موسى حسن في عينيه.","11:1":"وكلم الرب موسى وهارون قائلا لهما:","11:2":"«كلما بني إسرائيل قائلين: هذه هي الحيوانات التي تأكلونها من جميع البهائم التي على الأرض:","11:3":"كل ما شق ظلفا وقسمه ظلفين, ويجتر من البهائم, فإياه تأكلون.","11:4":"إلا هذه فلا تأكلوها مما يجتر ومما يشق الظلف: الجمل, لأنه يجتر لكنه لا يشق ظلفا, فهو نجس لكم.","11:5":"والوبر, لأنه يجتر لكنه لا يشق ظلفا, فهو نجس لكم.","11:6":"والأرنب, لأنه يجتر لكنه لا يشق ظلفا, فهو نجس لكم.","11:7":"والخنزير, لأنه يشق ظلفا ويقسمه ظلفين, لكنه لا يجتر, فهو نجس لكم.","11:8":"من لحمها لا تأكلوا وجثثها لا تلمسوا. إنها نجسة لكم.","11:9":"«وهذا تأكلونه من جميع ما في المياه: كل ما له زعانف وحرشف في المياه, في البحار وفي الأنهار, فإياه تأكلون.","11:10":"لكن كل ما ليس له زعانف وحرشف في البحار وفي الأنهار, من كل دبيب في المياه ومن كل نفس حية في المياه, فهو مكروه لكم,","11:11":"ومكروها يكون لكم. من لحمه لا تأكلوا, وجثته تكرهون.","11:12":"كل ما ليس له زعانف وحرشف في المياه فهو مكروه لكم.","11:13":"«وهذه تكرهونها من الطيور. لا تؤكل. إنها مكروهة: النسر والأنوق والعقاب","11:14":"والحدأة والباشق على أجناسه,","11:15":"وكل غراب على أجناسه,","11:16":"والنعامة والظليم والسأف والباز على أجناسه,","11:17":"والبوم والغواص والكركي","11:18":"والبجع والقوق والرخم","11:19":"واللقلق والببغا على أجناسه, والهدهد والخفاش.","11:20":"وكل دبيب الطير الماشي على أربع. فهو مكروه لكم.","11:21":"إلا هذا تأكلونه من جميع دبيب الطير الماشي على أربع: ما له كراعان فوق رجليه يثب بهما على الأرض.","11:22":"هذا منه تأكلون: الجراد على أجناسه, والدبا على أجناسه, والحرجوان على أجناسه, والجندب على أجناسه.","11:23":"لكن سائر دبيب الطير الذي له أربع أرجل فهو مكروه لكم.","11:24":"من هذه تتنجسون. كل من مس جثثها يكون نجسا إلى المساء,","11:25":"وكل من حمل من جثثها يغسل ثيابه ويكون نجسا إلى المساء.","11:26":"وجميع البهائم التي لها ظلف ولكن لا تشقه شقا أو لا تجتر, فهي نجسة لكم. كل من مسها يكون نجسا.","11:27":"وكل ما يمشي على كفوفه من جميع الحيوانات الماشية على أربع, فهو نجس لكم. كل من مس جثثها يكون نجسا إلى المساء.","11:28":"ومن حمل جثثها يغسل ثيابه ويكون نجسا إلى المساء. إنها نجسة لكم.","11:29":"«وهذا هو النجس لكم من الدبيب الذي يدب على الأرض: ابن عرس والفأر والضب على أجناسه,","11:30":"والحرذون والورل والوزغة والعظاية والحرباء.","11:31":"هذه هي النجسة لكم من كل الدبيب. كل من مسها بعد موتها يكون نجسا إلى المساء,","11:32":"وكل ما وقع عليه واحد منها بعد موتها يكون نجسا. من كل متاع خشب أو ثوب أو جلد أو بلاس. كل متاع يعمل به عمل يلقى في الماء ويكون نجسا إلى المساء ثم يطهر.","11:33":"وكل متاع خزف وقع فيه منها, فكل ما فيه يتنجس, وأما هو فتكسرونه.","11:34":"ما يأتي عليه ماء من كل طعام يؤكل يكون نجسا. وكل شراب يشرب في كل متاع يكون نجسا.","11:35":"وكل ما وقع عليه واحدة من جثثها يكون نجسا. التنور والموقدة يهدمان. إنها نجسة وتكون نجسة لكم.","11:36":"إلا العين والبئر, مجتمعي الماء, تكونان طاهرتين. لكن ما مس جثثها يكون نجسا.","11:37":"وإذا وقعت واحدة من جثثها على شيء من بزر زرع يزرع فهو طاهر.","11:38":"لكن إذا جعل ماء على بزر فوقع عليه واحدة من جثثها, فإنه نجس لكم.","11:39":"وإذا مات واحد من البهائم التي هي طعام لكم, فمن مس جثته يكون نجسا إلى المساء.","11:40":"ومن أكل من جثته يغسل ثيابه ويكون نجسا إلى المساء. ومن حمل جثته يغسل ثيابه ويكون نجسا إلى المساء.","11:41":"«وكل دبيب يدب على الأرض فهو مكروه لا يؤكل.","11:42":"كل ما يمشي على بطنه, وكل ما يمشي على أربع مع كل ما كثرت أرجله من كل دبيب يدب على الأرض, لا تأكلوه لأنه مكروه.","11:43":"لا تدنسوا أنفسكم بدبيب يدب, ولا تتنجسوا به, ولا تكونوا به نجسين.","11:44":"إني أنا الرب إلهكم فتتقدسون وتكونون قديسين, لأني أنا قدوس. ولا تنجسوا أنفسكم بدبيب يدب على الأرض.","11:45":"إني أنا الرب الذي أصعدكم من أرض مصر ليكون لكم إلها. فتكونون قديسين لأني أنا قدوس.","11:46":"هذه شريعة البهائم والطيور وكل نفس حية تسعى في الماء وكل نفس تدب على الأرض,","11:47":"للتمييز بين النجس والطاهر, وبين الحيوانات التي تؤكل, والحيوانات التي لا تؤكل».","12:1":"وكلم الرب موسى قائلا:","12:2":"«كلم بني إسرائيل قائلا: إذا حبلت امرأة وولدت ذكرا, تكون نجسة سبعة أيام. كما في أيام طمث علتها تكون نجسة.","12:3":"وفي اليوم الثامن يختن لحم غرلته.","12:4":"ثم تقيم ثلاثة وثلاثين يوما في دم تطهيرها. كل شيء مقدس لا تمس, وإلى المقدس لا تجئ حتى تكمل أيام تطهيرها.","12:5":"وإن ولدت أنثى, تكون نجسة أسبوعين كما في طمثها. ثم تقيم ستة وستين يوما في دم تطهيرها.","12:6":"ومتى كملت أيام تطهيرها لأجل ابن أو ابنة, تأتي بخروف حولي محرقة, وفرخ حمامة أو يمامة ذبيحة خطية إلى باب خيمة الاجتماع, إلى الكاهن,","12:7":"فيقدمهما أمام الرب ويكفر عنها, فتطهر من ينبوع دمها. هذه شريعة التي تلد ذكرا أو أنثى.","12:8":"وإن لم تنل يدها كفاية لشاة تأخذ يمامتين أو فرخي حمام, الواحد محرقة, والآخر ذبيحة خطية, فيكفر عنها الكاهن فتطهر».","13:1":"وكلم الرب موسى وهارون قائلا:","13:2":"«إذا كان إنسان في جلد جسده ناتئ أو قوباء أو لمعة تصير في جلد جسده ضربة برص, يؤتى به إلى هارون الكاهن أو إلى أحد بنيه الكهنة.","13:3":"فإن رأى الكاهن الضربة في جلد الجسد, وفي الضربة شعر قد ابيض, ومنظر الضربة أعمق من جلد جسده, فهي ضربة برص. فمتى رآه الكاهن يحكم بنجاسته.","13:4":"لكن إن كانت الضربة لمعة بيضاء في جلد جسده, ولم يكن منظرها أعمق من الجلد, ولم يبيض شعرها, يحجز الكاهن المضروب سبعة أيام.","13:5":"فإن رآه الكاهن في اليوم السابع وإذا في عينه الضربة قد وقفت, ولم تمتد الضربة في الجلد, يحجزه الكاهن سبعة أيام ثانية.","13:6":"فإن رآه الكاهن في اليوم السابع ثانية وإذا الضربة كامدة اللون, ولم تمتد الضربة في الجلد, يحكم الكاهن بطهارته. إنها حزاز. فيغسل ثيابه ويكون طاهرا.","13:7":"لكن إن كانت القوباء تمتد في الجلد بعد عرضه على الكاهن لتطهيره, يعرض على الكاهن ثانية.","13:8":"فإن رأى الكاهن وإذا القوباء قد امتدت في الجلد, يحكم الكاهن بنجاسته. إنها برص.","13:9":"«إن كانت في إنسان ضربة برص فيؤتى به إلى الكاهن.","13:10":"فإن رأى الكاهن وإذا في الجلد ناتئ أبيض, قد صير الشعر أبيض, وفي الناتئ وضح من لحم حي,","13:11":"فهو برص مزمن في جلد جسده. فيحكم الكاهن بنجاسته. لا يحجزه لأنه نجس.","13:12":"لكن إن كان البرص قد أفرخ في الجلد, وغطى البرص كل جلد المضروب من رأسه إلى قدميه حسب كل ما تراه عينا الكاهن,","13:13":"ورأى الكاهن وإذا البرص قد غطى كل جسمه, يحكم بطهارة المضروب. كله قد ابيض. إنه طاهر.","13:14":"لكن يوم يرى فيه لحم حي يكون نجسا.","13:15":"فمتى رأى الكاهن اللحم الحي يحكم بنجاسته. اللحم الحي نجس. إنه برص.","13:16":"ثم إن عاد اللحم الحي وابيض يأتي إلى الكاهن.","13:17":"فإن رآه الكاهن وإذا الضربة قد صارت بيضاء, يحكم الكاهن بطهارة المضروب. إنه طاهر.","13:18":"«وإذا كان الجسم في جلده دملة قد برئت,","13:19":"وصار في موضع الدملة ناتئ أبيض, أو لمعة بيضاء ضاربة إلى الحمرة, يعرض على الكاهن.","13:20":"فإن رأى الكاهن وإذا منظرها أعمق من الجلد وقد ابيض شعرها, يحكم الكاهن بنجاسته. إنها ضربة برص أفرخت في الدملة.","13:21":"لكن إن رآها الكاهن وإذا ليس فيها شعر أبيض, وليست أعمق من الجلد, وهي كامدة اللون, يحجزه الكاهن سبعة أيام.","13:22":"فإن كانت قد امتدت في الجلد يحكم الكاهن بنجاسته. إنها ضربة.","13:23":"لكن إن وقفت اللمعة مكانها ولم تمتد, فهي أثر الدملة. فيحكم الكاهن بطهارته.","13:24":"«أو إذا كان الجسم في جلده كي نار, وكان حي الكي لمعة بيضاء ضاربة إلى الحمرة أو بيضاء,","13:25":"ورآها الكاهن وإذا الشعر في اللمعة قد ابيض, ومنظرها أعمق من الجلد, فهي برص قد أفرخ في الكي. فيحكم الكاهن بنجاسته. إنها ضربة برص.","13:26":"لكن إن رآها الكاهن وإذا ليس في اللمعة شعر أبيض, وليست أعمق من الجلد, وهي كامدة اللون, يحجزه الكاهن سبعة أيام,","13:27":"ثم يراه الكاهن في اليوم السابع. فإن كانت قد امتدت في الجلد, يحكم الكاهن بنجاسته. إنها ضربة برص.","13:28":"لكن إن وقفت اللمعة مكانها, لم تمتد في الجلد, وكانت كامدة اللون, فهي ناتئ الكي, فالكاهن يحكم بطهارته لأنها أثر الكي.","13:29":"«وإذا كان رجل أو امرأة فيه ضربة في الرأس أو في الذقن,","13:30":"ورأى الكاهن الضربة وإذا منظرها أعمق من الجلد, وفيها شعر أشقر دقيق, يحكم الكاهن بنجاسته. إنها قرع. برص الرأس أو الذقن.","13:31":"لكن إذا رأى الكاهن ضربة القرع وإذا منظرها ليس أعمق من الجلد, لكن ليس فيها شعر أسود, يحجز الكاهن المضروب بالقرع سبعة أيام.","13:32":"فإن رأى الكاهن الضربة في اليوم السابع وإذا القرع لم يمتد, ولم يكن فيه شعر أشقر, ولا منظر القرع أعمق من الجلد,","13:33":"فليحلق. لكن لا يحلق القرع. ويحجز الكاهن الأقرع سبعة أيام ثانية.","13:34":"فإن رأى الكاهن الأقرع في اليوم السابع وإذا القرع لم يمتد في الجلد, وليس منظره أعمق من الجلد, يحكم الكاهن بطهارته, فيغسل ثيابه ويكون طاهرا.","13:35":"لكن إن كان القرع يمتد في الجلد بعد الحكم بطهارته,","13:36":"ورآه الكاهن وإذا القرع قد امتد في الجلد, فلا يفتش الكاهن على الشعر الأشقر. إنه نجس.","13:37":"لكن إن وقف في عينيه ونبت فيه شعر أسود, فقد برئ القرع. إنه طاهر فيحكم الكاهن بطهارته.","13:38":"«وإذا كان رجل أو امرأة في جلد جسده لمع, لمع بيض,","13:39":"ورأى الكاهن وإذا في جلد جسده لمع كامدة اللون بيضاء, فذلك بهق قد أفرخ في الجلد. إنه طاهر.","13:40":"«وإذا كان إنسان قد ذهب شعر رأسه فهو أقرع. إنه طاهر.","13:41":"وإن ذهب شعر رأسه من جهة وجهه فهو أصلع. إنه طاهر.","13:42":"لكن إذا كان في القرعة أو في الصلعة ضربة بيضاء ضاربة إلى الحمرة, فهو برص مفرخ في قرعته أو في صلعته.","13:43":"فإن رآه الكاهن وإذا ناتئ الضربة أبيض ضارب إلى الحمرة في قرعته أو في صلعته, كمنظر البرص في جلد الجسد,","13:44":"فهو إنسان أبرص. إنه نجس. فيحكم الكاهن بنجاسته. إن ضربته في رأسه.","13:45":"والأبرص الذي فيه الضربة, تكون ثيابه مشقوقة, ورأسه يكون مكشوفا, ويغطي شاربيه, وينادي: نجس, نجس.","13:46":"كل الأيام التي تكون الضربة فيه يكون نجسا. إنه نجس. يقيم وحده. خارج المحلة يكون مقامه.","13:47":"«وأما الثوب فإذا كان فيه ضربة برص, ثوب صوف أو ثوب كتان,","13:48":"في السدى أو اللحمة من الصوف أو الكتان, أو في جلد أو في كل مصنوع من جلد,","13:49":"وكانت الضربة ضاربة إلى الخضرة أو إلى الحمرة في الثوب أو في الجلد, في السدى أو اللحمة أو في متاع ما من جلد, فإنها ضربة برص, فتعرض على الكاهن.","13:50":"فيرى الكاهن الضربة ويحجز المضروب سبعة أيام.","13:51":"فمتى رأى الضربة في اليوم السابع إذا كانت الضربة قد امتدت في الثوب, في السدى أو اللحمة أو في الجلد من كل ما يصنع من جلد للعمل, فالضربة برص مفسد. إنها نجسة.","13:52":"فيحرق الثوب أو السدى أو اللحمة من الصوف أو الكتان أو متاع الجلد الذي كانت فيه الضربة, لأنها برص مفسد. بالنار يحرق.","13:53":"لكن إن رأى الكاهن وإذا الضربة لم تمتد في الثوب في السدى أو اللحمة أو في متاع الجلد,","13:54":"يأمر الكاهن أن يغسلوا ما فيه الضربة, ويحجزه سبعة أيام ثانية.","13:55":"فإن رأى الكاهن بعد غسل المضروب وإذا الضربة لم تغير منظرها, ولا امتدت الضربة, فهو نجس. بالنار تحرقه. إنها نخروب في جردة باطنه أو ظاهره.","13:56":"لكن إن رأى الكاهن وإذا الضربة كامدة اللون بعد غسله, يمزقها من الثوب أو الجلد من السدى أو اللحمة.","13:57":"ثم إن ظهرت أيضا في الثوب في السدى أو اللحمة أو في متاع الجلد فهي مفرخة. بالنار تحرق ما فيه الضربة.","13:58":"وأما الثوب, السدى أو اللحمة أو متاع الجلد الذي تغسله وتزول منه الضربة, فيغسل ثانية فيطهر.","13:59":"«هذه شريعة ضربة البرص في الصوف أو الكتان, في السدى أو اللحمة أو في كل متاع من جلد, للحكم بطهارته أو نجاسته».","14:1":"وكلم الرب موسى قائلا:","14:2":"«هذه تكون شريعة الأبرص: يوم طهره, يؤتى به إلى الكاهن.","14:3":"ويخرج الكاهن إلى خارج المحلة, فإن رأى الكاهن وإذا ضربة البرص قد برئت من الأبرص,","14:4":"يأمر الكاهن أن يؤخذ للمتطهر عصفوران حيان طاهران, وخشب أرز وقرمز وزوفا.","14:5":"ويأمر الكاهن أن يذبح العصفور الواحد في إناء خزف على ماء حي.","14:6":"أما العصفور الحي فيأخذه مع خشب الأرز والقرمز والزوفا ويغمسها مع العصفور الحي في دم العصفور المذبوح على الماء الحي,","14:7":"وينضح على المتطهر من البرص سبع مرات فيطهره, ثم يطلق العصفور الحي على وجه الصحراء.","14:8":"فيغسل المتطهر ثيابه ويحلق كل شعره ويستحم بماء فيطهر. ثم يدخل المحلة, لكن يقيم خارج خيمته سبعة أيام.","14:9":"وفي اليوم السابع يحلق كل شعره: رأسه ولحيته وحواجب عينيه وجميع شعره يحلق. ويغسل ثيابه ويرحض جسده بماء فيطهر.","14:10":"ثم في اليوم الثامن يأخذ خروفين صحيحين ونعجة واحدة حولية صحيحة وثلاثة أعشار دقيق تقدمة ملتوتة بزيت ولج زيت.","14:11":"فيوقف الكاهن المطهر الإنسان المتطهر وإياها أمام الرب لدى باب خيمة الاجتماع.","14:12":"ثم يأخذ الكاهن الخروف الواحد ويقربه ذبيحة إثم مع لج الزيت. يرددهما ترديدا أمام الرب.","14:13":"ويذبح الخروف في الموضع الذي يذبح فيه ذبيحة الخطية والمحرقة في المكان المقدس, لأن ذبيحة الإثم كذبيحة الخطية للكاهن. إنها قدس أقداس.","14:14":"ويأخذ الكاهن من دم ذبيحة الإثم ويجعل الكاهن على شحمة أذن المتطهر اليمنى, وعلى إبهام يده اليمنى, وعلى إبهام رجله اليمنى.","14:15":"ويأخذ الكاهن من لج الزيت ويصب في كف الكاهن اليسرى.","14:16":"ويغمس الكاهن إصبعه اليمنى في الزيت الذي على كفه اليسرى, وينضح من الزيت بإصبعه سبع مرات أمام الرب.","14:17":"ومما فضل من الزيت الذي في كفه يجعل الكاهن على شحمة أذن المتطهر اليمنى, وعلى إبهام يده اليمنى, وعلى إبهام رجله اليمنى, على دم ذبيحة الإثم.","14:18":"والفاضل من الزيت الذي في كف الكاهن يجعله على رأس المتطهر, ويكفر عنه الكاهن أمام الرب.","14:19":"ثم يعمل الكاهن ذبيحة الخطية ويكفر عن المتطهر من نجاسته. ثم يذبح المحرقة.","14:20":"ويصعد الكاهن المحرقة والتقدمة على المذبح ويكفر عنه الكاهن فيطهر.","14:21":"«لكن إن كان فقيرا ولا تنال يده, يأخذ خروفا واحدا ذبيحة إثم لترديد, تكفيرا عنه, وعشرا واحدا من دقيق ملتوت بزيت لتقدمة, ولج زيت,","14:22":"ويمامتين أو فرخي حمام كما تنال يده, فيكون الواحد ذبيحة خطية, والآخر محرقة.","14:23":"ويأتي بها في اليوم الثامن لطهره إلى الكاهن, إلى باب خيمة الاجتماع أمام الرب.","14:24":"فيأخذ الكاهن كبش الإثم ولج الزيت, ويرددهما الكاهن ترديدا أمام الرب.","14:25":"ثم يذبح كبش الإثم, ويأخذ الكاهن من دم ذبيحة الإثم ويجعل على شحمة أذن المتطهر اليمنى, وعلى إبهام يده اليمنى, وعلى إبهام رجله اليمنى.","14:26":"ويصب الكاهن من الزيت في كف الكاهن اليسرى,","14:27":"وينضح الكاهن بإصبعه اليمنى من الزيت الذي في كفه اليسرى سبع مرات أمام الرب.","14:28":"ويجعل الكاهن من الزيت الذي في كفه على شحمة أذن المتطهر اليمنى, وعلى إبهام يده اليمنى, وعلى إبهام رجله اليمنى, على موضع دم ذبيحة الإثم.","14:29":"والفاضل من الزيت الذي في كف الكاهن يجعله على رأس المتطهر تكفيرا عنه أمام الرب.","14:30":"ثم يعمل واحدة من اليمامتين أو من فرخي الحمام, مما تنال يده.","14:31":"ما تنال يده: الواحد ذبيحة خطية, والآخر محرقة مع التقدمة. ويكفر الكاهن عن المتطهر أمام الرب.","14:32":"هذه شريعة الذي فيه ضربة برص الذي لا تنال يده في تطهيره».","14:33":"وكلم الرب موسى وهارون قائلا:","14:34":"«متى جئتم إلى أرض كنعان التي أعطيكم ملكا, وجعلت ضربة برص في بيت في أرض ملككم.","14:35":"يأتي الذي له البيت, ويخبر الكاهن قائلا: قد ظهر لي شبه ضربة في البيت.","14:36":"فيأمر الكاهن أن يفرغوا البيت قبل دخول الكاهن ليرى الضربة, لئلا يتنجس كل ما في البيت. وبعد ذلك يدخل الكاهن ليرى البيت.","14:37":"فإذا رأى الضربة, وإذا الضربة في حيطان البيت نقر ضاربة إلى الخضرة أو إلى الحمرة, ومنظرها أعمق من الحائط,","14:38":"يخرج الكاهن من البيت إلى باب البيت, ويغلق البيت سبعة أيام.","14:39":"فإذا رجع الكاهن في اليوم السابع ورأى وإذا الضربة قد امتدت في حيطان البيت,","14:40":"يأمر الكاهن أن يقلعوا الحجارة التي فيها الضربة ويطرحوها خارج المدينة في مكان نجس.","14:41":"ويقشر البيت من داخل حواليه, ويطرحون التراب الذي يقشرونه خارج المدينة في مكان نجس.","14:42":"ويأخذون حجارة أخرى ويدخلونها في مكان الحجارة, ويأخذ ترابا آخر ويطين البيت.","14:43":"فإن رجعت الضربة وأفرخت في البيت بعد قلع الحجارة وقشر البيت وتطيينه,","14:44":"وأتى الكاهن ورأى وإذا الضربة قد امتدت في البيت, فهي برص مفسد في البيت. إنه نجس.","14:45":"فيهدم البيت: حجارته وأخشابه وكل تراب البيت, ويخرجها إلى خارج المدينة إلى مكان نجس.","14:46":"ومن دخل إلى البيت في كل أيام انغلاقه, يكون نجسا إلى المساء.","14:47":"ومن نام في البيت يغسل ثيابه. ومن أكل في البيت يغسل ثيابه.","14:48":"لكن إن أتى الكاهن ورأى وإذا الضربة لم تمتد في البيت بعد تطيين البيت, يطهر الكاهن البيت. لأن الضربة قد برئت.","14:49":"فيأخذ لتطهير البيت عصفورين وخشب أرز وقرمزا وزوفا.","14:50":"ويذبح العصفور الواحد في إناء خزف على ماء حي,","14:51":"ويأخذ خشب الأرز والزوفا والقرمز والعصفور الحي ويغمسها في دم العصفور المذبوح وفي الماء الحي, وينضح البيت سبع مرات,","14:52":"ويطهر البيت بدم العصفور وبالماء الحي وبالعصفور الحي وبخشب الأرز وبالزوفا وبالقرمز.","14:53":"ثم يطلق العصفور الحي إلى خارج المدينة على وجه الصحراء ويكفر عن البيت فيطهر.","14:54":"«هذه هي الشريعة لكل ضربة من البرص وللقرع,","14:55":"ولبرص الثوب والبيت,","14:56":"وللناتئ وللقوباء وللمعة,","14:57":"للتعليم في يوم النجاسة ويوم الطهارة. هذه شريعة البرص».","15:1":"وكلم الرب موسى وهارون قائلا:","15:2":"«كلما بني إسرائيل وقولا لهم: كل رجل يكون له سيل من لحمه, فسيله نجس.","15:3":"وهذه تكون نجاسته بسيله: إن كان لحمه يبصق سيله, أو يحتبس لحمه عن سيله, فذلك نجاسته.","15:4":"كل فراش يضطجع عليه الذي له السيل يكون نجسا, وكل متاع يجلس عليه يكون نجسا.","15:5":"ومن مس فراشه يغسل ثيابه ويستحم بماء, ويكون نجسا إلى المساء.","15:6":"ومن جلس على المتاع الذي يجلس عليه ذو السيل, يغسل ثيابه ويستحم بماء, ويكون نجسا إلى المساء.","15:7":"ومن مس لحم ذي السيل يغسل ثيابه ويستحم بماء, ويكون نجسا إلى المساء.","15:8":"وإن بصق ذو السيل على طاهر, يغسل ثيابه ويستحم بماء, ويكون نجسا إلى المساء.","15:9":"وكل ما يركب عليه ذو السيل يكون نجسا.","15:10":"وكل من مس كل ما كان تحته يكون نجسا إلى المساء, ومن حملهن يغسل ثيابه ويستحم بماء, ويكون نجسا إلى المساء.","15:11":"وكل من مسه ذو السيل ولم يغسل يديه بماء, يغسل ثيابه ويستحم بماء ويكون نجسا إلى المساء.","15:12":"وإناء الخزف الذي يمسه ذو السيل يكسر. وكل إناء خشب يغسل بماء.","15:13":"وإذا طهر ذو السيل من سيله, يحسب له سبعة أيام لطهره, ويغسل ثيابه ويرحض جسده بماء حي فيطهر.","15:14":"وفي اليوم الثامن يأخذ لنفسه يمامتين أو فرخي حمام, ويأتي إلى أمام الرب, إلى باب خيمة الاجتماع, ويعطيهما للكاهن,","15:15":"فيعملهما الكاهن: الواحد ذبيحة خطية, والآخر محرقة. ويكفر عنه الكاهن أمام الرب من سيله.","15:16":"«وإذا حدث من رجل اضطجاع زرع, يرحض كل جسده بماء, ويكون نجسا إلى المساء.","15:17":"وكل ثوب وكل جلد يكون عليه اضطجاع زرع يغسل بماء, ويكون نجسا إلى المساء.","15:18":"والمرأة التي يضطجع معها رجل اضطجاع زرع, يستحمان بماء, ويكونان نجسين إلى المساء.","15:19":"«وإذا كانت امرأة لها سيل, وكان سيلها دما في لحمها, فسبعة أيام تكون في طمثها. وكل من مسها يكون نجسا إلى المساء.","15:20":"وكل ما تضطجع عليه في طمثها يكون نجسا, وكل ما تجلس عليه يكون نجسا.","15:21":"وكل من مس فراشها يغسل ثيابه ويستحم بماء, ويكون نجسا إلى المساء.","15:22":"وكل من مس متاعا تجلس عليه, يغسل ثيابه ويستحم بماء, ويكون نجسا إلى المساء.","15:23":"وإن كان على الفراش أو على المتاع الذي هي جالسة عليه عندما يمسه, يكون نجسا إلى المساء.","15:24":"وإن اضطجع معها رجل فكان طمثها عليه يكون نجسا سبعة أيام. وكل فراش يضطجع عليه يكون نجسا.","15:25":"«وإذا كانت امرأة يسيل سيل دمها أياما كثيرة في غير وقت طمثها, أو إذا سال بعد طمثها, فتكون كل أيام سيلان نجاستها كما في أيام طمثها. إنها نجسة.","15:26":"كل فراش تضطجع عليه كل أيام سيلها يكون لها كفراش طمثها. وكل الأمتعة التي تجلس عليها تكون نجسة كنجاسة طمثها.","15:27":"وكل من مسهن يكون نجسا, فيغسل ثيابه ويستحم بماء, ويكون نجسا إلى المساء.","15:28":"وإذا طهرت من سيلها تحسب, لنفسها سبعة أيام ثم تطهر.","15:29":"وفي اليوم الثامن تأخذ لنفسها يمامتين أو فرخي حمام, وتأتي بهما إلى الكاهن إلى باب خيمة الاجتماع.","15:30":"فيعمل الكاهن: الواحد ذبيحة خطية, والآخر محرقة. ويكفر عنها الكاهن أمام الرب من سيل نجاستها.","15:31":"فتعزلان بني إسرائيل عن نجاستهم لئلا يموتوا في نجاستهم بتنجيسهم مسكني الذي في وسطهم.","15:32":"«هذه شريعة ذي السيل, والذي يحدث منه اضطجاع زرع فيتنجس بها,","15:33":"والعليلة في طمثها, والسائل سيله: الذكر والأنثى, والرجل الذي يضطجع مع نجسة».","16:1":"وكلم الرب موسى بعد موت ابني هارون عندما اقتربا أمام الرب وماتا.","16:2":"وقال الرب لموسى: «كلم هارون أخاك أن لا يدخل كل وقت إلى القدس داخل الحجاب أمام الغطاء الذي على التابوت لئلا يموت, لأني في السحاب أتراءى على الغطاء.","16:3":"بهذا يدخل هارون إلى القدس: بثور ابن بقر لذبيحة خطية, وكبش لمحرقة.","16:4":"يلبس قميص كتان مقدسا, وتكون سراويل كتان على جسده, ويتنطق بمنطقة كتان, ويتعمم بعمامة كتان. إنها ثياب مقدسة. فيرحض جسده بماء ويلبسها.","16:5":"ومن جماعة بني إسرائيل يأخذ تيسين من المعز لذبيحة خطية, وكبشا واحدا لمحرقة.","16:6":"ويقرب هارون ثور الخطية الذي له, ويكفر عن نفسه وعن بيته.","16:7":"ويأخذ التيسين ويوقفهما أمام الرب لدى باب خيمة الاجتماع.","16:8":"ويلقي هارون على التيسين قرعتين: قرعة للرب وقرعة لعزازيل.","16:9":"ويقرب هارون التيس الذي خرجت عليه القرعة للرب ويعمله ذبيحة خطية.","16:10":"وأما التيس الذي خرجت عليه القرعة لعزازيل فيوقف حيا أمام الرب, ليكفر عنه ليرسله إلى عزازيل إلى البرية.","16:11":"«ويقدم هارون ثور الخطية الذي له ويكفر عن نفسه وعن بيته, ويذبح ثور الخطية الذي له,","16:12":"ويأخذ ملء المجمرة جمر نار عن المذبح من أمام الرب, وملء راحتيه بخورا عطرا دقيقا, ويدخل بهما إلى داخل الحجاب","16:13":"ويجعل البخور على النار أمام الرب, فتغشي سحابة البخور الغطاء الذي على الشهادة فلا يموت.","16:14":"ثم يأخذ من دم الثور وينضح بإصبعه على وجه الغطاء إلى الشرق. وقدام الغطاء ينضح سبع مرات من الدم بإصبعه.","16:15":"«ثم يذبح تيس الخطية الذي للشعب, ويدخل بدمه إلى داخل الحجاب. ويفعل بدمه كما فعل بدم الثور: ينضحه على الغطاء وقدام الغطاء,","16:16":"فيكفر عن القدس من نجاسات بني إسرائيل ومن سيئاتهم مع كل خطاياهم. وهكذا يفعل لخيمة الاجتماع القائمة بينهم في وسط نجاساتهم.","16:17":"ولا يكن إنسان في خيمة الاجتماع من دخوله للتكفير في القدس إلى خروجه, فيكفر عن نفسه وعن بيته وعن كل جماعة إسرائيل.","16:18":"ثم يخرج إلى المذبح الذي أمام الرب ويكفر عنه. يأخذ من دم الثور ومن دم التيس ويجعل على قرون المذبح مستديرا.","16:19":"وينضح عليه من الدم بإصبعه سبع مرات, ويطهره ويقدسه من نجاسات بني إسرائيل.","16:20":"«ومتى فرغ من التكفير عن القدس وعن خيمة الاجتماع وعن المذبح, يقدم التيس الحي.","16:21":"ويضع هارون يديه على رأس التيس الحي ويقر عليه بكل ذنوب بني إسرائيل, وكل سيئاتهم مع كل خطاياهم, ويجعلها على رأس التيس, ويرسله بيد من يلاقيه إلى البرية,","16:22":"ليحمل التيس عليه كل ذنوبهم إلى أرض مقفرة, فيطلق التيس في البرية.","16:23":"ثم يدخل هارون إلى خيمة الاجتماع ويخلع ثياب الكتان التي لبسها عند دخوله إلى القدس ويضعها هناك.","16:24":"ويرحض جسده بماء في مكان مقدس, ثم يلبس ثيابه ويخرج ويعمل محرقته ومحرقة الشعب, ويكفر عن نفسه وعن الشعب.","16:25":"وشحم ذبيحة الخطية يوقده على المذبح.","16:26":"والذي أطلق التيس إلى عزازيل يغسل ثيابه ويرحض جسده بماء, وبعد ذلك يدخل إلى المحلة.","16:27":"وثور الخطية وتيس الخطية اللذان أتي بدمهما للتكفير في القدس يخرجهما إلى خارج المحلة, ويحرقون بالنار جلديهما ولحمهما وفرثهما.","16:28":"والذي يحرقهما يغسل ثيابه ويرحض جسده بماء, وبعد ذلك يدخل إلى المحلة.","16:29":"«ويكون لكم فريضة دهرية, أنكم في الشهر السابع في عاشر الشهر تذللون نفوسكم, وكل عمل لا تعملون: الوطني والغريب النازل في وسطكم.","16:30":"لأنه في هذا اليوم يكفر عنكم لتطهيركم. من جميع خطاياكم أمام الرب تطهرون.","16:31":"سبت عطلة هو لكم, وتذللون نفوسكم فريضة دهرية.","16:32":"ويكفر الكاهن الذي يمسحه, والذي يملأ يده للكهانة عوضا عن أبيه. يلبس ثياب الكتان, الثياب المقدسة,","16:33":"ويكفر عن مقدس القدس. وعن خيمة الاجتماع والمذبح يكفر. وعن الكهنة وكل شعب الجماعة يكفر.","16:34":"وتكون هذه لكم فريضة دهرية للتكفير عن بني إسرائيل من جميع خطاياهم مرة في السنة». ففعل كما أمر الرب موسى.","17:1":"وكلم الرب موسى قائلا:","17:2":"«كلم هارون وبنيه وجميع بني إسرائيل وقل لهم: هذا هو الأمر الذي يوصي به الرب قائلا:","17:3":"كل إنسان من بيت إسرائيل يذبح بقرا أو غنما أو معزى في المحلة, أو يذبح خارج المحلة,","17:4":"وإلى باب خيمة الاجتماع لا يأتي به ليقرب قربانا للرب أمام مسكن الرب, يحسب على ذلك الإنسان دم. قد سفك دما. فيقطع ذلك الإنسان من شعبه.","17:5":"لكي يأتي بنو إسرائيل بذبائحهم التي يذبحونها على وجه الصحراء ويقدموها للرب إلى باب خيمة الاجتماع إلى الكاهن, ويذبحوها ذبائح سلامة للرب.","17:6":"ويرش الكاهن الدم على مذبح الرب لدى باب خيمة الاجتماع, ويوقد الشحم لرائحة سرور للرب.","17:7":"ولا يذبحوا بعد ذبائحهم للتيوس التي هم يزنون وراءها. فريضة دهرية تكون هذه لهم في أجيالهم.","17:8":"«وتقول لهم: كل إنسان من بيت إسرائيل ومن الغرباء الذين ينزلون في وسطكم يصعد محرقة أو ذبيحة,","17:9":"ولا يأتي بها إلى باب خيمة الاجتماع ليصنعها للرب, يقطع ذلك الإنسان من شعبه.","17:10":"وكل إنسان من بيت إسرائيل ومن الغرباء النازلين في وسطكم يأكل دما, أجعل وجهي ضد النفس الآكلة الدم وأقطعها من شعبها,","17:11":"لأن نفس الجسد هي في الدم, فأنا أعطيتكم إياه على المذبح للتكفير عن نفوسكم, لأن الدم يكفر عن النفس.","17:12":"لذلك قلت لبني إسرائيل: لا تأكل نفس منكم دما, ولا يأكل الغريب النازل في وسطكم دما.","17:13":"وكل إنسان من بني إسرائيل ومن الغرباء النازلين في وسطكم يصطاد صيدا, وحشا أو طائرا يؤكل, يسفك دمه ويغطيه بالتراب.","17:14":"لأن نفس كل جسد دمه هو بنفسه, فقلت لبني إسرائيل: لا تأكلوا دم جسد ما, لأن نفس كل جسد هي دمه. كل من أكله يقطع.","17:15":"وكل إنسان يأكل ميتة أو فريسة, وطنيا كان أو غريبا, يغسل ثيابه ويستحم بماء, ويبقى نجسا إلى المساء ثم يكون طاهرا.","17:16":"وإن لم يغسل ولم يرحض جسده يحمل ذنبه».","18:1":"وكلم الرب موسى قائلا:","18:2":"«كلم بني إسرائيل وقل لهم: أنا الرب إلهكم.","18:3":"مثل عمل أرض مصر التي سكنتم فيها لا تعملوا, ومثل عمل أرض كنعان التي أنا آت بكم إليها لا تعملوا, وحسب فرائضهم لا تسلكوا.","18:4":"أحكامي تعملون, وفرائضي تحفظون لتسلكوا فيها. أنا الرب إلهكم.","18:5":"فتحفظون فرائضي وأحكامي, التي إذا فعلها الإنسان يحيا بها. أنا الرب.","18:6":"«لا يقترب إنسان إلى قريب جسده ليكشف العورة. أنا الرب.","18:7":"عورة أبيك وعورة أمك لا تكشف. إنها أمك لا تكشف عورتها.","18:8":"عورة امرأة أبيك لا تكشف. إنها عورة أبيك.","18:9":"عورة أختك بنت أبيك أو بنت أمك, المولودة في البيت أو المولودة خارجا, لا تكشف عورتها.","18:10":"عورة ابنة ابنك, أو ابنة ابنتك لا تكشف عورتها. إنها عورتك.","18:11":"عورة بنت امرأة أبيك المولودة من أبيك لا تكشف عورتها. إنها أختك.","18:12":"عورة أخت أبيك لا تكشف. إنها قريبة أبيك.","18:13":"عورة أخت أمك لا تكشف. إنها قريبة أمك.","18:14":"عورة أخي أبيك لا تكشف. إلى امرأته لا تقترب. إنها عمتك.","18:15":"عورة كنتك لا تكشف. إنها امرأة ابنك. لا تكشف عورتها.","18:16":"عورة امرأة أخيك لا تكشف. إنها عورة أخيك.","18:17":"عورة امرأة وبنتها لا تكشف. ولا تأخذ ابنة ابنها, أو ابنة بنتها لتكشف عورتها. إنهما قريبتاها. إنه رذيلة.","18:18":"ولا تأخذ امرأة على أختها للضر لتكشف عورتها معها في حياتها.","18:19":"«ولا تقترب إلى امرأة في نجاسة طمثها لتكشف عورتها.","18:20":"ولا تجعل مع امرأة صاحبك مضجعك لزرع, فتتنجس بها.","18:21":"ولا تعط من زرعك للإجازة لمولك لئلا تدنس اسم إلهك. أنا الرب.","18:22":"ولا تضاجع ذكرا مضاجعة امرأة. إنه رجس.","18:23":"ولا تجعل مع بهيمة مضجعك فتتنجس بها. ولا تقف امرأة أمام بهيمة لنزائها. إنه فاحشة.","18:24":"«بكل هذه لا تتنجسوا, لأنه بكل هذه قد تنجس الشعوب الذين أنا طاردهم من أمامكم","18:25":"فتنجست الأرض. فأجتزي ذنبها منها, فتقذف الأرض سكانها.","18:26":"لكن تحفظون أنتم فرائضي وأحكامي, ولا تعملون شيئا من جميع هذه الرجسات, لا الوطني ولا الغريب النازل في وسطكم,","18:27":"لأن جميع هذه الرجسات قد عملها أهل الأرض الذين قبلكم فتنجست الأرض.","18:28":"فلا تقذفكم الأرض بتنجيسكم إياها كما قذفت الشعوب التي قبلكم.","18:29":"بل كل من عمل شيئا من جميع هذه الرجسات تقطع الأنفس التي تعملها من شعبها.","18:30":"فتحفظون شعائري لكي لا تعملوا شيئا من الرسوم الرجسة التي عملت قبلكم ولا تتنجسوا بها. أنا الرب إلهكم».","19:1":"وكلم الرب موسى قائلا:","19:2":"«كلم كل جماعة بني إسرائيل وقل لهم: تكونون قديسين لأني قدوس الرب إلهكم.","19:3":"تهابون كل إنسان أمه وأباه, وتحفظون سبوتي. أنا الرب إلهكم.","19:4":"لا تلتفتوا إلى الأوثان, وآلهة مسبوكة لا تصنعوا لأنفسكم. أنا الرب إلهكم.","19:5":"ومتى ذبحتم ذبيحة سلامة للرب فللرضا عنكم تذبحونها.","19:6":"يوم تذبحونها تؤكل, وفي الغد. والفاضل إلى اليوم الثالث يحرق بالنار.","19:7":"وإذا أكلت في اليوم الثالث فذلك نجاسة لا يرضى به.","19:8":"ومن أكل منها يحمل ذنبه لأنه قد دنس قدس الرب. فتقطع تلك النفس من شعبها.","19:9":"«وعندما تحصدون حصيد أرضكم لا تكمل زوايا حقلك في الحصاد. ولقاط حصيدك لا تلتقط.","19:10":"وكرمك لا تعلله, ونثار كرمك لا تلتقط. للمسكين والغريب تتركه. أنا الرب إلهكم.","19:11":"«لا تسرقوا, ولا تكذبوا, ولا تغدروا أحدكم بصاحبه.","19:12":"ولا تحلفوا باسمي للكذب, فتدنس اسم إلهك. أنا الرب.","19:13":"«لا تغصب قريبك ولا تسلب, ولا تبت أجرة أجير عندك إلى الغد.","19:14":"لا تشتم الأصم, وقدام الأعمى لا تجعل معثرة, بل اخش إلهك. أنا الرب.","19:15":"لا ترتكبوا جورا في القضاء. لا تأخذوا بوجه مسكين ولا تحترم وجه كبير. بالعدل تحكم لقريبك.","19:16":"لا تسع في الوشاية بين شعبك. لا تقف على دم قريبك. أنا الرب.","19:17":"لا تبغض أخاك في قلبك. إنذارا تنذر صاحبك, ولا تحمل لأجله خطية.","19:18":"لا تنتقم ولا تحقد على أبناء شعبك, بل تحب قريبك كنفسك. أنا الرب.","19:19":"فرائضي تحفظون. لا تنز بهائمك جنسين, وحقلك لا تزرع صنفين, ولا يكن عليك ثوب مصنف من صنفين.","19:20":"وإذا اضطجع رجل مع امرأة اضطجاع زرع وهي أمة مخطوبة لرجل, ولم تفد فداء ولا أعطيت حريتها, فليكن تأديب. لا يقتلا لأنها لم تعتق.","19:21":"ويأتي إلى الرب بذبيحة لإثمه إلى باب خيمة الاجتماع: كبشا, ذبيحة إثم.","19:22":"فيكفر عنه الكاهن بكبش الإثم أمام الرب من خطيته التي أخطأ, فيصفح له عن خطيته التي أخطأ.","19:23":"«ومتى دخلتم الأرض وغرستم كل شجرة للطعام, تحسبون ثمرها غرلتها. ثلاث سنين تكون لكم غلفاء. لا يؤكل منها.","19:24":"وفي السنة الرابعة يكون كل ثمرها قدسا لتمجيد الرب.","19:25":"وفي السنة الخامسة تأكلون ثمرها, لتزيد لكم غلتها. أنا الرب إلهكم.","19:26":"«لا تأكلوا بالدم. لا تتفاءلوا ولا تعيفوا.","19:27":"لا تقصروا رؤوسكم مستديرا, ولا تفسد عارضيك.","19:28":"ولا تجرحوا أجسادكم لميت. وكتابة وسم لا تجعلوا فيكم. أنا الرب.","19:29":"لا تدنس ابنتك بتعريضها للزنى لئلا تزني الأرض وتمتلئ الأرض رذيلة.","19:30":"سبوتي تحفظون, ومقدسي تهابون. أنا الرب.","19:31":"لا تلتفتوا إلى الجان ولا تطلبوا التوابع, فتتنجسوا بهم. أنا الرب إلهكم.","19:32":"من أمام الأشيب تقوم وتحترم وجه الشيخ, وتخشى إلهك. أنا الرب.","19:33":"«وإذا نزل عندك غريب في أرضكم فلا تظلموه.","19:34":"كالوطني منكم يكون لكم الغريب النازل عندكم, وتحبه كنفسك, لأنكم كنتم غرباء في أرض مصر. أنا الرب إلهكم.","19:35":"لا ترتكبوا جورا في القضاء, لا في القياس, ولا في الوزن, ولا في الكيل.","19:36":"ميزان حق, ووزنات حق, وإيفة حق, وهين حق تكون لكم. أنا الرب إلهكم الذي أخرجكم من أرض مصر.","19:37":"فتحفظون كل فرائضي, وكل أحكامي, وتعملونها. أنا الرب».","20:1":"وكلم الرب موسى قائلا:","20:2":"«وتقول لبني إسرائيل: كل إنسان من بني إسرائيل ومن الغرباء النازلين في إسرائيل أعطى من زرعه لمولك فإنه يقتل. يرجمه شعب الأرض بالحجارة.","20:3":"وأجعل أنا وجهي ضد ذلك الإنسان, وأقطعه من شعبه, لأنه أعطى من زرعه لمولك لكي ينجس مقدسي, ويدنس اسمي القدوس.","20:4":"وإن غمض شعب الأرض أعينهم عن ذلك الإنسان عندما يعطي من زرعه لمولك, فلم يقتلوه,","20:5":"فإني أضع وجهي ضد ذلك الإنسان, وضد عشيرته, وأقطعه وجميع الفاجرين وراءه, بالزنى وراء مولك من شعبهم.","20:6":"والنفس التي تلتفت إلى الجان, وإلى التوابع لتزني وراءهم, أجعل وجهي ضد تلك النفس وأقطعها من شعبها.","20:7":"فتتقدسون وتكونون قديسين, لأني أنا الرب إلهكم.","20:8":"وتحفظون فرائضي وتعملونها. أنا الرب مقدسكم.","20:9":"«كل إنسان سب أباه أو أمه فإنه يقتل. قد سب أباه أو أمه. دمه عليه.","20:10":"وإذا زنى رجل مع امرأة, فإذا زنى مع امرأة قريبه, فإنه يقتل الزاني والزانية.","20:11":"وإذا اضطجع رجل مع امرأة أبيه, فقد كشف عورة أبيه. إنهما يقتلان كلاهما. دمهما عليهما.","20:12":"وإذا اضطجع رجل مع كنته, فإنهما يقتلان كلاهما. قد فعلا فاحشة. دمهما عليهما.","20:13":"وإذا اضطجع رجل مع ذكر اضطجاع امرأة, فقد فعلا كلاهما رجسا. إنهما يقتلان. دمهما عليهما.","20:14":"وإذا اتخذ رجل امرأة وأمها فذلك رذيلة. بالنار يحرقونه وإياهما, لكي لا يكون رذيلة بينكم.","20:15":"وإذا جعل رجل مضجعه مع بهيمة, فإنه يقتل, والبهيمة تميتونها.","20:16":"وإذا اقتربت امرأة إلى بهيمة لنزائها, تميت المرأة والبهيمة. إنهما يقتلان. دمهما عليهما.","20:17":"وإذا أخذ رجل أخته بنت أبيه أو بنت أمه, ورأى عورتها ورأت هي عورته, فذلك عار. يقطعان أمام أعين بني شعبهما. قد كشف عورة أخته. يحمل ذنبه.","20:18":"وإذا اضطجع رجل مع امرأة طامث وكشف عورتها, عرى ينبوعها وكشفت هي ينبوع دمها, يقطعان كلاهما من شعبهما.","20:19":"عورة أخت أمك, أو أخت أبيك لا تكشف. إنه قد عرى قريبته. يحملان ذنبهما.","20:20":"وإذا اضطجع رجل مع امرأة عمه فقد كشف عورة عمه. يحملان ذنبهما. يموتان عقيمين.","20:21":"وإذا أخذ رجل امرأة أخيه, فذلك نجاسة. قد كشف عورة أخيه. يكونان عقيمين.","20:22":"«فتحفظون جميع فرائضي وجميع أحكامي, وتعملونها لكي لا تقذفكم الأرض التي أنا آت بكم إليها لتسكنوا فيها.","20:23":"ولا تسلكون في رسوم الشعوب الذين أنا طاردهم من أمامكم. لأنهم قد فعلوا كل هذه, فكرهتهم.","20:24":"وقلت لكم: ترثون أنتم أرضهم, وأنا أعطيكم إياها لترثوها, أرضا تفيض لبنا وعسلا. أنا الرب إلهكم الذي ميزكم من الشعوب.","20:25":"فتميزون بين البهائم الطاهرة والنجسة, وبين الطيور النجسة والطاهرة. فلا تدنسوا نفوسكم بالبهائم والطيور, ولا بكل ما يدب على الأرض مما ميزته لكم ليكون نجسا.","20:26":"وتكونون لي قديسين لأني قدوس أنا الرب, وقد ميزتكم من الشعوب لتكونوا لي.","20:27":"«وإذا كان في رجل أو امرأة جان أو تابعة فإنه يقتل. بالحجارة يرجمونه. دمه عليه».","21:1":"وقال الرب لموسى: «كلم الكهنة بني هارون وقل لهم: لا يتنجس أحد منكم لميت في قومه,","21:2":"إلا لأقربائه الأقرب إليه: أمه وأبيه وابنه وابنته وأخيه","21:3":"وأخته العذراء القريبة إليه التي لم تصر لرجل. لأجلها يتنجس.","21:4":"كزوج لا يتنجس بأهله لتدنيسه.","21:5":"لا يجعلوا قرعة في رؤوسهم, ولا يحلقوا عوارض لحاهم, ولا يجرحوا جراحة في أجسادهم.","21:6":"مقدسين يكونون لإلههم, ولا يدنسون اسم إلههم, لأنهم يقربون وقائد الرب طعام إلههم, فيكونون قدسا.","21:7":"إمرأة زانية أو مدنسة لا يأخذوا, ولا يأخذوا امرأة مطلقة من زوجها. لأنه مقدس لإلهه.","21:8":"فتحسبه مقدسا لأنه يقرب خبز إلهك. مقدسا يكون عندك لأني قدوس أنا الرب مقدسكم.","21:9":"وإذا تدنست ابنة كاهن بالزنى فقد دنست أباها. بالنار تحرق.","21:10":"«والكاهن الأعظم بين إخوته الذي صب على رأسه دهن المسحة, وملئت يده ليلبس الثياب, لا يكشف رأسه, ولا يشق ثيابه,","21:11":"ولا يأتي إلى نفس ميتة, ولا يتنجس لأبيه أو أمه,","21:12":"ولا يخرج من المقدس لئلا يدنس مقدس إلهه, لأن إكليل دهن مسحة إلهه عليه. أنا الرب.","21:13":"هذا يأخذ امرأة عذراء.","21:14":"أما الأرملة والمطلقة والمدنسة والزانية فمن هؤلاء لا يأخذ, بل يتخذ عذراء من قومه امرأة.","21:15":"ولا يدنس زرعه بين شعبه لأني أنا الرب مقدسه».","21:16":"وكلم الرب موسى قائلا:","21:17":"«كلم هارون قائلا: إذا كان رجل من نسلك في أجيالهم فيه عيب فلا يتقدم ليقرب خبز إلهه.","21:18":"لأن كل رجل فيه عيب لا يتقدم. لا رجل أعمى ولا أعرج, ولا أفطس ولا زوائدي,","21:19":"ولا رجل فيه كسر رجل أو كسر يد,","21:20":"ولا أحدب ولا أكشم, ولا من في عينه بياض, ولا أجرب ولا أكلف, ولا مرضوض الخصى.","21:21":"كل رجل فيه عيب من نسل هارون الكاهن لا يتقدم ليقرب وقائد الرب. فيه عيب لا يتقدم ليقرب خبز إلهه.","21:22":"خبز إلهه من قدس الأقداس ومن القدس يأكل.","21:23":"لكن إلى الحجاب لا يأتي, وإلى المذبح لا يقترب, لأن فيه عيبا, لئلا يدنس مقدسي, لأني أنا الرب مقدسهم».","21:24":"فكلم موسى هارون وبنيه وكل بني إسرائيل.","22:1":"وكلم الرب موسى قائلا:","22:2":"«كلم هارون وبنيه أن يتوقوا أقداس بني إسرائيل التي يقدسونها لي ولا يدنسوا اسمي القدوس. أنا الرب.","22:3":"قل لهم: في أجيالكم كل إنسان من جميع نسلكم اقترب إلى الأقداس التي يقدسها بنو إسرائيل للرب, ونجاسته عليه, تقطع تلك النفس من أمامي. أنا الرب.","22:4":"كل إنسان من نسل هارون وهو أبرص أو ذو سيل, لا يأكل من الأقداس حتى يطهر. ومن مس شيئا نجسا لميت, أو إنسان حدث منه اضطجاع زرع,","22:5":"أو إنسان مس دبيبا يتنجس به, أو إنسانا يتنجس به لنجاسة فيه,","22:6":"فالذي يمس ذلك يكون نجسا إلى المساء, ولا يأكل من الأقداس, بل يرحض جسده بماء.","22:7":"فمتى غربت الشمس يكون طاهرا, ثم يأكل من الأقداس لأنها طعامه.","22:8":"ميتة أو فريسة لا يأكل فيتنجس بها. أنا الرب.","22:9":"فيحفظون شعائري لكي لا يحملوا لأجلها خطية يموتون بها لأنهم يدنسونها. أنا الرب مقدسهم.","22:10":"«وكل أجنبي لا يأكل قدسا. نزيل كاهن وأجيره لا يأكلون قدسا.","22:11":"لكن إذا اشترى كاهن أحدا شراء فضة, فهو يأكل منه, والمولود في بيته. هما يأكلان من طعامه.","22:12":"وإذا صارت ابنة كاهن لرجل أجنبي لا تأكل من رفيعة الأقداس.","22:13":"وأما ابنة كاهن قد صارت أرملة أو مطلقة, ولم يكن لها نسل, ورجعت إلى بيت أبيها كما في صباها, فتأكل من طعام أبيها. لكن كل أجنبي لا يأكل منه.","22:14":"وإذا أكل إنسان قدسا سهوا, يزيد عليه خمسه ويدفع القدس للكاهن.","22:15":"فلا يدنسون أقداس بني إسرائيل التي يرفعونها للرب,","22:16":"فيحملونهم ذنب إثم بأكلهم أقداسهم. لأني أنا الرب مقدسهم».","22:17":"وكلم الرب موسى قائلا:","22:18":"«كلم هارون وبنيه وجميع بني إسرائيل وقل لهم: كل إنسان من بيت إسرائيل ومن الغرباء في إسرائيل, قرب قربانه من جميع نذورهم وجميع نوافلهم التي يقربونها للرب محرقة,","22:19":"فللرضا عنكم يكون ذكرا صحيحا من البقر أو الغنم أو المعز.","22:20":"كل ما كان فيه عيب لا تقربوه لأنه لا يكون للرضا عنكم.","22:21":"وإذا قرب إنسان ذبيحة سلامة للرب وفاء لنذر, أو نافلة من البقر أو الأغنام, تكون صحيحة للرضا. كل عيب لا يكون فيها.","22:22":"الأعمى والمكسور والمجروح والبثير والأجرب والأكلف, هذه لا تقربوها للرب, ولا تجعلوا منها وقودا على المذبح للرب.","22:23":"وأما الثور أو الشاة الزوائدي أو القزم فنافلة تعمله, ولكن لنذر لا يرضى به.","22:24":"ومرضوض الخصية ومسحوقها ومقطوعها لا تقربوا للرب. وفي أرضكم لا تعملوها.","22:25":"ومن يد ابن الغريب لا تقربوا خبز إلهكم من جميع هذه, لأن فيها فسادها. فيها عيب لا يرضى بها عنكم».","22:26":"وكلم الرب موسى قائلا:","22:27":"«متى ولد بقر أو غنم أو معزى يكون سبعة أيام تحت أمه, ثم من اليوم الثامن فصاعدا يرضى به قربان وقود للرب.","22:28":"وأما البقرة أو الشاة فلا تذبحوها وابنها في يوم واحد.","22:29":"ومتى ذبحتم ذبيحة شكر للرب, فللرضا عنكم تذبحونها.","22:30":"في ذلك اليوم تؤكل. لا تبقوا منها إلى الغد. أنا الرب.","22:31":"فتحفظون وصاياي وتعملونها. أنا الرب.","22:32":"ولا تدنسون اسمي القدوس, فأتقدس في وسط بني إسرائيل. أنا الرب مقدسكم","22:33":"الذي أخرجكم من أرض مصر ليكون لكم إلها. أنا الرب».","23:1":"وكلم الرب موسى قائلا:","23:2":"«كلم بني إسرائيل وقل لهم: مواسم الرب التي فيها تنادون محافل مقدسة. هذه هي مواسمي:","23:3":"ستة أيام يعمل عمل, وأما اليوم السابع ففيه سبت عطلة محفل مقدس. عملا ما لا تعملوا. إنه سبت للرب في جميع مساكنكم.","23:4":"«هذه مواسم الرب, المحافل المقدسة التي تنادون بها في أوقاتها:","23:5":"في الشهر الأول, في الرابع عشر من الشهر, بين العشاءين فصح للرب.","23:6":"وفي اليوم الخامس عشر من هذا الشهر عيد الفطير للرب. سبعة أيام تأكلون فطيرا.","23:7":"في اليوم الأول يكون لكم محفل مقدس. عملا ما من الشغل لا تعملوا.","23:8":"وسبعة أيام تقربون وقودا للرب. في اليوم السابع يكون محفل مقدس. عملا ما من الشغل لا تعملوا».","23:9":"وكلم الرب موسى قائلا:","23:10":"«كلم بني إسرائيل وقل لهم: متى جئتم إلى الأرض التي أنا أعطيكم وحصدتم حصيدها, تأتون بحزمة أول حصيدكم إلى الكاهن.","23:11":"فيردد الحزمة أمام الرب للرضا عنكم. في غد السبت يرددها الكاهن.","23:12":"وتعملون يوم ترديدكم الحزمة خروفا صحيحا حوليا محرقة للرب.","23:13":"وتقدمته عشرين من دقيق ملتوت بزيت, وقودا للرب رائحة سرور, وسكيبه ربع الهين من خمر.","23:14":"وخبزا وفريكا وسويقا لا تأكلوا إلى هذا اليوم عينه, إلى أن تأتوا بقربان إلهكم, فريضة دهرية في أجيالكم في جميع مساكنكم.","23:15":"«ثم تحسبون لكم من غد السبت من يوم إتيانكم بحزمة الترديد سبعة أسابيع تكون كاملة.","23:16":"إلى غد السبت السابع تحسبون خمسين يوما, ثم تقربون تقدمة جديدة للرب.","23:17":"من مساكنكم تأتون بخبز ترديد, رغيفين عشرين يكونان من دقيق, ويخبزان خميرا باكورة للرب.","23:18":"وتقربون مع الخبز سبعة خراف صحيحة حولية, وثورا واحدا ابن بقر, وكبشين محرقة للرب مع تقدمتها وسكيبها وقود رائحة سرور للرب.","23:19":"وتعملون تيسا واحدا من المعز ذبيحة خطية, وخروفين حوليين ذبيحة سلامة.","23:20":"فيرددها الكاهن مع خبز الباكورة ترديدا أمام الرب مع الخروفين, فتكون للكاهن قدسا للرب.","23:21":"وتنادون في ذلك اليوم عينه محفلا مقدسا يكون لكم. عملا ما من الشغل لا تعملوا. فريضة دهرية في جميع مساكنكم في أجيالكم.","23:22":"وعندما تحصدون حصيد أرضكم, لا تكمل زوايا حقلك في حصادك, ولقاط حصيدك لا تلتقط. للمسكين والغريب تتركه. أنا الرب إلهكم».","23:23":"وكلم الرب موسى قائلا:","23:24":"«كلم بني إسرائيل قائلا: في الشهر السابع, في أول الشهر يكون لكم عطلة, تذكار هتاف البوق, محفل مقدس.","23:25":"عملا ما من الشغل لا تعملوا, لكن تقربون وقودا للرب».","23:26":"وكلم الرب موسى قائلا:","23:27":"«أما العاشر من هذا الشهر السابع, فهو يوم الكفارة. محفلا مقدسا يكون لكم. تذللون نفوسكم وتقربون وقودا للرب.","23:28":"عملا ما لا تعملوا في هذا اليوم عينه, لأنه يوم كفارة للتكفير عنكم أمام الرب إلهكم.","23:29":"إن كل نفس لا تتذلل في هذا اليوم عينه تقطع من شعبها.","23:30":"وكل نفس تعمل عملا ما في هذا اليوم عينه أبيد تلك النفس من شعبها.","23:31":"عملا ما لا تعملوا. فريضة دهرية في أجيالكم في جميع مساكنكم.","23:32":"إنه سبت عطلة لكم, فتذللون نفوسكم. في تاسع الشهر عند المساء. من المساء إلى المساء تسبتون سبتكم».","23:33":"وكلم الرب موسى قائلا:","23:34":"«كلم بني إسرائيل قائلا: في اليوم الخامس عشر من هذا الشهر السابع عيد المظال سبعة أيام للرب.","23:35":"في اليوم الأول محفل مقدس. عملا ما من الشغل لا تعملوا.","23:36":"سبعة أيام تقربون وقودا للرب. في اليوم الثامن يكون لكم محفل مقدس تقربون وقودا للرب. إنه اعتكاف. كل عمل شغل لا تعملوا.","23:37":"«هذه هي مواسم الرب التي فيها تنادون محافل مقدسة لتقريب وقود للرب, محرقة وتقدمة وذبيحة وسكيبا أمر اليوم بيومه,","23:38":"عدا سبوت الرب, وعدا عطاياكم وجميع نذوركم, وجميع نوافلكم التي تعطونها للرب.","23:39":"أما اليوم الخامس عشر من الشهر السابع ففيه, عندما تجمعون غلة الأرض, تعيدون عيدا للرب سبعة أيام. في اليوم الأول عطلة وفي اليوم الثامن عطلة.","23:40":"وتأخذون لأنفسكم في اليوم الأول ثمر أشجار بهجة وسعف النخل وأغصان أشجار غبياء وصفصاف الوادي, وتفرحون أمام الرب إلهكم سبعة أيام.","23:41":"تعيدونه عيدا للرب سبعة أيام في السنة فريضة دهرية في أجيالكم. في الشهر السابع تعيدونه.","23:42":"في مظال تسكنون سبعة أيام. كل الوطنيين في إسرائيل يسكنون في المظال.","23:43":"لكي تعلم أجيالكم أني في مظال أسكنت بني إسرائيل لما أخرجتهم من أرض مصر. أنا الرب إلهكم».","23:44":"فأخبر موسى بني إسرائيل بمواسم الرب.","24:1":"وكلم الرب موسى قائلا:","24:2":"«أوص بني إسرائيل أن يقدموا إليك زيت زيتون مرضوض نقيا للضوء لإيقاد السرج دائما.","24:3":"خارج حجاب الشهادة في خيمة الاجتماع يرتبها هارون من المساء إلى الصباح أمام الرب دائما فريضة دهرية في أجيالكم.","24:4":"على المنارة الطاهرة يرتب السرج أمام الرب دائما.","24:5":"«وتأخذ دقيقا وتخبزه اثني عشر قرصا. عشرين يكون القرص الواحد.","24:6":"وتجعلها صفين, كل صف ستة على المائدة الطاهرة أمام الرب.","24:7":"وتجعل على كل صف لبانا نقيا فيكون للخبز تذكارا وقودا للرب.","24:8":"في كل يوم سبت يرتبه أمام الرب دائما, من عند بني إسرائيل ميثاقا دهريا.","24:9":"فيكون لهارون وبنيه, فيأكلونه في مكان مقدس, لأنه قدس أقداس له من وقائد الرب فريضة دهرية».","24:10":"وخرج ابن امرأة إسرائيلية, وهو ابن رجل مصري, في وسط بني إسرائيل. وتخاصم في المحلة ابن الإسرائيلية ورجل إسرائيلي.","24:11":"فجدف ابن الإسرائيلية على الاسم وسب. فأتوا به إلى موسى. وكان اسم أمه شلومية بنت دبري من سبط دان.","24:12":"فوضعوه في المحرس ليعلن لهم عن فم الرب.","24:13":"فكلم الرب موسى قائلا:","24:14":"«أخرج الذي سب إلى خارج المحلة, فيضع جميع السامعين أيديهم على رأسه, ويرجمه كل الجماعة.","24:15":"وكلم بني إسرائيل قائلا: كل من سب إلهه يحمل خطيته,","24:16":"ومن جدف على اسم الرب فإنه يقتل. يرجمه كل الجماعة رجما. الغريب كالوطني عندما يجدف على الاسم يقتل.","24:17":"وإذا أمات أحد إنسانا فإنه يقتل.","24:18":"ومن أمات بهيمة يعوض عنها نفسا بنفس.","24:19":"وإذا أحدث إنسان في قريبه عيبا, فكما فعل كذلك يفعل به.","24:20":"كسر بكسر, وعين بعين, وسن بسن. كما أحدث عيبا في الإنسان كذلك يحدث فيه.","24:21":"من قتل بهيمة يعوض عنها, ومن قتل إنسانا يقتل.","24:22":"حكم واحد يكون لكم. الغريب يكون كالوطني. إني أنا الرب إلهكم».","24:23":"فكلم موسى بني إسرائيل أن يخرجوا الذي سب إلى خارج المحلة ويرجموه بالحجارة. ففعل بنو إسرائيل كما أمر الرب موسى.","25:1":"وكلم الرب موسى في جبل سيناء قائلا:","25:2":"«كلم بني إسرائيل وقل لهم: متى أتيتم إلى الأرض التي أنا أعطيكم تسبت الأرض سبتا للرب.","25:3":"ست سنين تزرع حقلك, وست سنين تقضب كرمك وتجمع غلتهما.","25:4":"وأما السنة السابعة ففيها يكون للأرض سبت عطلة, سبتا للرب. لا تزرع حقلك ولا تقضب كرمك.","25:5":"زريع حصيدك لا تحصد, وعنب كرمك المحول لا تقطف. سنة عطلة تكون للأرض.","25:6":"ويكون سبت الأرض لكم طعاما. لك ولعبدك ولأمتك ولأجيرك ولمستوطنك النازلين عندك,","25:7":"ولبهائمك وللحيوان الذي في أرضك تكون كل غلتها طعاما.","25:8":"«وتعد لك سبعة سبوت سنين. سبع سنين سبع مرات. فتكون لك أيام السبعة السبوت السنوية تسعا وأربعين سنة.","25:9":"ثم تعبر بوق الهتاف في الشهر السابع في عاشر الشهر. في يوم الكفارة تعبرون البوق في جميع أرضكم.","25:10":"وتقدسون السنة الخمسين, وتنادون بالعتق في الأرض لجميع سكانها. تكون لكم يوبيلا, وترجعون كل إلى ملكه, وتعودون كل إلى عشيرته.","25:11":"يوبيلا تكون لكم السنة الخمسون. لا تزرعوا ولا تحصدوا زريعها, ولا تقطفوا كرمها المحول.","25:12":"إنها يوبيل. مقدسة تكون لكم. من الحقل تأكلون غلتها.","25:13":"في سنة اليوبيل هذه ترجعون كل إلى ملكه.","25:14":"فمتى بعت صاحبك مبيعا, أو اشتريت من يد صاحبك, فلا يغبن أحدكم أخاه.","25:15":"حسب عدد السنين بعد اليوبيل تشتري من صاحبك, وحسب سني الغلة يبيعك.","25:16":"على قدر كثرة السنين تكثر ثمنه, وعلى قدر قلة السنين تقلل ثمنه, لأنه عدد الغلات يبيعك.","25:17":"فلا يغبن أحدكم صاحبه, بل اخش إلهك. إني أنا الرب إلهكم.","25:18":"فتعملون فرائضي وتحفظون أحكامي وتعملونها لتسكنوا على الأرض آمنين.","25:19":"وتعطي الأرض ثمرها فتأكلون للشبع, وتسكنون عليها آمنين.","25:20":"وإذا قلتم: ماذا نأكل في السنة السابعة إن لم نزرع ولم نجمع غلتنا؟","25:21":"فإني آمر ببركتي لكم في السنة السادسة, فتعمل غلة لثلاث سنين.","25:22":"فتزرعون السنة الثامنة وتأكلون من الغلة العتيقة إلى السنة التاسعة. إلى أن تأتي غلتها تأكلون عتيقا.","25:23":"«والأرض لا تباع بتة, لأن لي الأرض, وأنتم غرباء ونزلاء عندي.","25:24":"بل في كل أرض ملككم تجعلون فكاكا للأرض.","25:25":"إذا افتقر أخوك فباع من ملكه, يأتي وليه الأقرب إليه ويفك مبيع أخيه.","25:26":"ومن لم يكن له ولي, فإن نالت يده ووجد مقدار فكاكه,","25:27":"يحسب سني بيعه, ويرد الفاضل للإنسان الذي باع له, فيرجع إلى ملكه.","25:28":"وإن لم تنل يده كفاية ليرد له, يكون مبيعه في يد شاريه إلى سنة اليوبيل, ثم يخرج في اليوبيل فيرجع إلى ملكه.","25:29":"«وإذا باع إنسان بيت سكن في مدينة ذات سور, فيكون فكاكه إلى تمام سنة بيعه. سنة يكون فكاكه.","25:30":"وإن لم يفك قبل أن تكمل له سنة تامة, وجب البيت الذي في المدينة ذات السور بتة لشاريه في أجياله. لا يخرج في اليوبيل.","25:31":"لكن بيوت القرى التي ليس لها سور حولها, فمع حقول الأرض تحسب. يكون لها فكاك, وفي اليوبيل تخرج.","25:32":"وأما مدن اللاويين, بيوت مدن ملكهم, فيكون لها فكاك مؤبد للاويين.","25:33":"والذي يفكه من اللاويين المبيع من بيت أو من مدينة ملكه يخرج في اليوبيل, لأن بيوت مدن اللاويين هي ملكهم في وسط بني إسرائيل.","25:34":"وأما حقول المسارح لمدنهم فلا تباع, لأنها ملك دهري لهم.","25:35":"«وإذا افتقر أخوك وقصرت يده عندك, فاعضده غريبا أو مستوطنا فيعيش معك.","25:36":"لا تأخذ منه ربا ولا مرابحة, بل اخش إلهك, فيعيش أخوك معك.","25:37":"فضتك لا تعطه بالربا, وطعامك لا تعط بالمرابحة.","25:38":"أنا الرب إلهكم الذي أخرجكم من أرض مصر ليعطيكم أرض كنعان, فيكون لكم إلها.","25:39":"«وإذا افتقر أخوك عندك وبيع لك, فلا تستعبده استعباد عبد.","25:40":"كأجير, كنزيل يكون عندك. إلى سنة اليوبيل يخدم عندك,","25:41":"ثم يخرج من عندك هو وبنوه معه ويعود إلى عشيرته, وإلى ملك آبائه يرجع.","25:42":"لأنهم عبيدي الذين أخرجتهم من أرض مصر, لا يباعون بيع العبيد.","25:43":"لا تتسلط عليه بعنف, بل اخش إلهك.","25:44":"وأما عبيدك وإماؤك الذين يكونون لك, فمن الشعوب الذين حولكم. منهم تقتنون عبيدا وإماء.","25:45":"وأيضا من أبناء المستوطنين النازلين عندكم, منهم تقتنون ومن عشائرهم الذين عندكم الذين يلدونهم في أرضكم, فيكونون ملكا لكم.","25:46":"وتستملكونهم لأبنائكم من بعدكم ميراث ملك. تستعبدونهم إلى الدهر. وأما إخوتكم بنو إسرائيل فلا يتسلط إنسان على أخيه بعنف.","25:47":"«وإذا طالت يد غريب أو نزيل عندك, وافتقر أخوك عنده وبيع للغريب المستوطن عندك أو لنسل عشيرة الغريب,","25:48":"فبعد بيعه يكون له فكاك. يفكه واحد من إخوته,","25:49":"أو يفكه عمه أو ابن عمه, أو يفكه واحد من أقرباء جسده من عشيرته, أو إذا نالت يده يفك نفسه.","25:50":"فيحاسب شاريه من سنة بيعه له إلى سنة اليوبيل, ويكون ثمن بيعه حسب عدد السنين. كأيام أجير يكون عنده.","25:51":"إن بقي كثير من السنين فعلى قدرها يرد فكاكه من ثمن شرائه.","25:52":"وإن بقي قليل من السنين إلى سنة اليوبيل يحسب له وعلى قدر سنيه يرد فكاكه.","25:53":"كأجير من سنة إلى سنة يكون عنده. لا يتسلط عليه بعنف أمام عينيك.","25:54":"وإن لم يفك بهؤلاء, يخرج في سنة اليوبيل هو وبنوه معه,","25:55":"لأن بني إسرائيل لي عبيد. هم عبيدي الذين أخرجتهم من أرض مصر. أنا الرب إلهكم.","26:1":"«لا تصنعوا لكم أوثانا, ولا تقيموا لكم تمثالا منحوتا أو نصبا, ولا تجعلوا في أرضكم حجرا مصورا لتسجدوا له. لأني أنا الرب إلهكم.","26:2":"سبوتي تحفظون ومقدسي تهابون. أنا الرب.","26:3":"«إذا سلكتم في فرائضي وحفظتم وصاياي وعملتم بها,","26:4":"أعطي مطركم في حينه, وتعطي الأرض غلتها, وتعطي أشجار الحقل أثمارها,","26:5":"ويلحق دراسكم بالقطاف, ويلحق القطاف بالزرع, فتأكلون خبزكم للشبع وتسكنون في أرضكم آمنين.","26:6":"وأجعل سلاما في الأرض, فتنامون وليس من يزعجكم. وأبيد الوحوش الرديئة من الأرض, ولا يعبر سيف في أرضكم.","26:7":"وتطردون أعداءكم فيسقطون أمامكم بالسيف.","26:8":"يطرد خمسة منكم مئة, ومئة منكم يطردون ربوة, ويسقط أعداؤكم أمامكم بالسيف.","26:9":"وألتفت إليكم وأثمركم وأكثركم وأفي ميثاقي معكم,","26:10":"فتأكلون العتيق المعتق, وتخرجون العتيق من وجه الجديد.","26:11":"وأجعل مسكني في وسطكم, ولا ترذلكم نفسي.","26:12":"وأسير بينكم وأكون لكم إلها وأنتم تكونون لي شعبا.","26:13":"أنا الرب إلهكم الذي أخرجكم من أرض مصر من كونكم لهم عبيدا, وقطع قيود نيركم وسيركم قياما.","26:14":"«لكن إن لم تسمعوا لي ولم تعملوا كل هذه الوصايا,","26:15":"وإن رفضتم فرائضي وكرهت أنفسكم أحكامي, فما عملتم كل وصاياي, بل نكثتم ميثاقي,","26:16":"فإني أعمل هذه بكم: أسلط عليكم رعبا وسلا وحمى تفني العينين وتتلف النفس. وتزرعون باطلا زرعكم فيأكله أعداؤكم.","26:17":"وأجعل وجهي ضدكم فتنهزمون أمام أعدائكم, ويتسلط عليكم مبغضوكم, وتهربون وليس من يطردكم.","26:18":"«وإن كنتم مع ذلك لا تسمعون لي, أزيد على تأديبكم سبعة أضعاف حسب خطاياكم,","26:19":"فأحطم فخار عزكم, وأصير سماءكم كالحديد, وأرضكم كالنحاس,","26:20":"فتفرغ باطلا قوتكم, وأرضكم لا تعطي غلتها, وأشجار الأرض لا تعطي أثمارها.","26:21":"«وإن سلكتم معي بالخلاف, ولم تشاءوا أن تسمعوا لي, أزيد عليكم ضربات سبعة أضعاف حسب خطاياكم.","26:22":"أطلق عليكم وحوش البرية فتعدمكم الأولاد, وتقرض بهائمكم, وتقللكم فتوحش طرقكم.","26:23":"«وإن لم تتأدبوا مني بذلك, بل سلكتم معي بالخلاف,","26:24":"فإني أنا أسلك معكم بالخلاف, وأضربكم سبعة أضعاف حسب خطاياكم.","26:25":"أجلب عليكم سيفا ينتقم نقمة الميثاق, فتجتمعون إلى مدنكم وأرسل في وسطكم الوبأ فتدفعون بيد العدو.","26:26":"بكسري لكم عصا الخبز. تخبز عشر نساء خبزكم في تنور واحد, ويرددن خبزكم بالوزن, فتأكلون ولا تشبعون.","26:27":"«وإن كنتم بذلك لا تسمعون لي بل سلكتم معي بالخلاف,","26:28":"فأنا أسلك معكم بالخلاف ساخطا, وأؤدبكم سبعة أضعاف حسب خطاياكم,","26:29":"فتأكلون لحم بنيكم, ولحم بناتكم تأكلون.","26:30":"وأخرب مرتفعاتكم, وأقطع شمساتكم, وألقي جثثكم على جثث أصنامكم, وترذلكم نفسي.","26:31":"وأصير مدنكم خربة, ومقادسكم موحشة, ولا أشتم رائحة سروركم.","26:32":"وأوحش الأرض فيستوحش منها أعداؤكم الساكنون فيها.","26:33":"وأذريكم بين الأمم, وأجرد وراءكم السيف فتصير أرضكم موحشة, ومدنكم تصير خربة.","26:34":"حينئذ تستوفي الأرض سبوتها كل أيام وحشتها وأنتم في أرض أعدائكم. حينئذ تسبت الأرض وتستوفي سبوتها.","26:35":"كل أيام وحشتها تسبت ما لم تسبته من سبوتكم في سكنكم عليها.","26:36":"والباقون منكم ألقي الجبانة في قلوبهم في أراضي أعدائهم, فيهزمهم صوت ورقة مندفعة, فيهربون كالهرب من السيف, ويسقطون وليس طارد.","26:37":"ويعثر بعضهم ببعض كما من أمام السيف وليس طارد, ولا يكون لكم قيام أمام أعدائكم,","26:38":"فتهلكون بين الشعوب وتأكلكم أرض أعدائكم.","26:39":"والباقون منكم يفنون بذنوبهم في أراضي أعدائكم. وأيضا بذنوب آبائهم معهم يفنون.","26:40":"لكن إن أقروا بذنوبهم وذنوب آبائهم في خيانتهم التي خانوني بها, وسلوكهم معي الذي سلكوا بالخلاف,","26:41":"وإني أيضا سلكت معهم بالخلاف وأتيت بهم إلى أرض أعدائهم. إلا أن تخضع حينئذ قلوبهم الغلف, ويستوفوا حينئذ عن ذنوبهم,","26:42":"أذكر ميثاقي مع يعقوب, وأذكر أيضا ميثاقي مع إسحاق, وميثاقي مع إبراهيم, وأذكر الأرض.","26:43":"والأرض تترك منهم وتستوفي سبوتها في وحشتها منهم, وهم يستوفون عن ذنوبهم لأنهم قد أبوا أحكامي وكرهت أنفسهم فرائضي.","26:44":"ولكن مع ذلك أيضا متى كانوا في أرض أعدائهم, ما أبيتهم ولا كرهتهم حتى أبيدهم وأنكث ميثاقي معهم, لأني أنا الرب إلههم.","26:45":"بل أذكر لهم الميثاق مع الأولين الذين أخرجتهم من أرض مصر أمام أعين الشعوب لأكون لهم إلها. أنا الرب».","26:46":"هذه هي الفرائض والأحكام والشرائع التي وضعها الرب بينه وبين بني إسرائيل في جبل سيناء بيد موسى.","27:1":"وكلم الرب موسى قائلا:","27:2":"«كلم بني إسرائيل وقل لهم: إذا أفرز إنسان نذرا حسب تقويمك نفوسا للرب,","27:3":"فإن كان تقويمك لذكر من ابن عشرين سنة إلى ابن ستين سنة, يكون تقويمك خمسين شاقل فضة على شاقل المقدس.","27:4":"وإن كان أنثى يكون تقويمك ثلاثين شاقلا.","27:5":"وإن كان من ابن خمس سنين إلى ابن عشرين سنة يكون تقويمك لذكر عشرين شاقلا, ولأنثى عشرة شواقل.","27:6":"وإن كان من ابن شهر إلى ابن خمس سنين يكون تقويمك لذكر خمسة شواقل فضة, ولأنثى يكون تقويمك ثلاثة شواقل فضة.","27:7":"وإن كان من ابن ستين سنة فصاعدا فإن كان ذكرا يكون تقويمك خمسة عشر شاقلا, وأما للأنثى فعشرة شواقل.","27:8":"وإن كان فقيرا عن تقويمك يوقفه أمام الكاهن فيقومه الكاهن. على قدر ما تنال يد الناذر يقومه الكاهن.","27:9":"«وإن كان بهيمة مما يقربونه قربانا للرب, فكل ما يعطي منه للرب يكون قدسا.","27:10":"لا يغيره ولا يبدله جيدا برديء, أو رديئا بجيد. وإن أبدل بهيمة ببهيمة تكون هي وبديلها قدسا.","27:11":"وإن كان بهيمة نجسة مما لا يقربونه قربانا للرب يوقف البهيمة أمام الكاهن,","27:12":"فيقومها الكاهن جيدة أم رديئة. فحسب تقويمك يا كاهن هكذا يكون.","27:13":"فإن فكها يزيد خمسها على تقويمك.","27:14":"«وإذا قدس إنسان بيته قدسا للرب, يقومه الكاهن جيدا أم رديئا. وكما يقومه الكاهن هكذا يقوم.","27:15":"فإن كان المقدس يفك بيته, يزيد خمس فضة تقويمك عليه فيكون له.","27:16":"وإن قدس إنسان بعض حقل ملكه للرب, يكون تقويمك على قدر بذاره. بذار حومر من الشعير بخمسين شاقل فضة.","27:17":"إن قدس حقله من سنة اليوبيل فحسب تقويمك يقوم.","27:18":"وإن قدس حقله بعد سنة اليوبيل يحسب له الكاهن الفضة على قدر السنين الباقية إلى سنة اليوبيل, فينقص من تقويمك.","27:19":"فإن فك الحقل مقدسه, يزيد خمس فضة تقويمك عليه فيجب له.","27:20":"لكن إن لم يفك الحقل وبيع الحقل لإنسان آخر لا يفك بعد,","27:21":"بل يكون الحقل عند خروجه في اليوبيل قدسا للرب كالحقل المحرم. للكاهن يكون ملكه.","27:22":"«وإن قدس للرب حقلا من شرائه ليس من حقول ملكه,","27:23":"يحسب له الكاهن مبلغ تقويمك إلى سنة اليوبيل, فيعطي تقويمك في ذلك اليوم قدسا للرب.","27:24":"وفي سنة اليوبيل يرجع الحقل إلى الذي اشتراه منه, إلى الذي له ملك الأرض.","27:25":"وكل تقويمك يكون على شاقل المقدس. عشرين جيرة يكون الشاقل.","27:26":"«لكن البكر الذي يفرز بكرا للرب من البهائم فلا يقدسه أحد. ثورا كان أو شاة فهو للرب.","27:27":"وإن كان من البهائم النجسة يفديه حسب تقويمك ويزيد خمسه عليه. وإن لم يفك, فيباع حسب تقويمك.","27:28":"أما كل محرم يحرمه إنسان للرب من كل ما له من الناس والبهائم ومن حقول ملكه فلا يباع ولا يفك. إن كل محرم هو قدس أقداس للرب.","27:29":"كل محرم يحرم من الناس لا يفدى. يقتل قتلا.","27:30":"«وكل عشر الأرض من حبوب الأرض وأثمار الشجر فهو للرب. قدس للرب.","27:31":"وإن فك إنسان بعض عشره يزيد خمسه عليه.","27:32":"وأما كل عشر البقر والغنم فكل ما يعبر تحت العصا يكون العاشر قدسا للرب.","27:33":"لا يفحص أجيد هو أم رديء, ولا يبدله. وإن أبدله يكون هو وبديله قدسا. لا يفك».","27:34":"هذه هي الوصايا التي أوصى الرب بها موسى إلى بني إسرائيل في جبل سيناء."};
